window.__LEX={"G2800":"<h1>klasis</h1>\n<p>Strong n° 2800 <i>Prononciation [klas'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une brisure, rompre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλαίω</b>, <i>att</i>. <b>κλάω</b> <span>[ᾱ]</span> <span>(<i>impf</i>. ἔκλαιον, <i>att</i>. ἔκλαον <span>[ᾱ]</span>, <i>f</i>. κλαύσομαι, <i>att</i>. κλαιήσω <i>ou</i> κλαήσω, <i>ao</i>. ἔκλαυσα, <i>pf. inus. ; pass. ao</i>. ἐκλαύσθην, <i>pf</i>. κέκλαυμαι, <i>postér</i>. κέκλαυσμαι)</span><br><b>   I <i>intr.</i></b> pleurer, <i>etc. ;</i> δάκρυσι, DC. <i>59, 27,</i> verser des larmes ; ἀμφί τινα, IL. <i>18, 240,</i> pleurer sur qqn ; κλάειν τινὶ λέγειν, AR. <i>Pl. 62, ou</i> κελεύειν, AR. <i>Ach. 1129, Eq. 433,</i> souhaiter du mal à qqn (<i>p. opp. à</i> χαίρειν τινὶ λέγειν) ; αὐτὸν κλαίοντα ἀφήσω, IL. <i>2, 263,</i> je te renverrai pleurant, <i>càd</i>. battu, meurtri ; κλαίοντά τινα καθιστάναι, XÉN. <i>Mem. 2, 1, 12,</i> faire pleurer qqn, le maltraiter ; <i>p. suite,</i> κλαύσεται, AR. <i>Vesp. 1327, etc</i>. il s’en repentira ; κλάοις ἄν, εἰ, ESCHL. <i>Suppl. 925,</i> tu t’en repentirais, si, <i>etc. ; au part. prés</i>. κλάων, SOPH. <i>O.R. 401, 1152 ; Ant. 754,</i> à tes risques et périls, pour ton malheur ;<br><b>   II <i>tr</i>.<br>      1</b> pleurer sur, déplorer : τινά, IL. <i>20, 210, etc. ;</i> OD. <i>1, 363 ;</i> ESCHL. <i>Sept. 828,</i> pleurer qqn ; <i>au pass</i>. κεκλαυμένος, ESCHL. <i>Ch. 687,</i> pleuré ; τι, ESCHL. <i>fr. 285 ;</i> SOPH. <i>El. 1117, 1122 ;</i> PLAT. <i>Rsp. 388</i> c ; PLUT. <i>Alc. 33,</i> déplorer qqe ch. ;<br><b>      2</b> appeler en criant, <i>acc</i>. ARR. <i>Epict. 2, 16, 38 ;</i><br><b><i>Moy.</i></b> :<br><b>      1 <i>intr.</i></b> pleurer pour soi <i>ou</i> sur soi, ESCHL. <i>Sept. 920, Ag. 1096 ;</i> SOPH. <i>Tr. 153 ; d’où postér</i>. κεκλαυμένος, ESCHL. <i>Ch. 447, 731 ;</i> SOPH. <i>O.R. 1490,</i> qui est en larmes ;<br><b>      2 <i>tr.</i></b> pleurer <i>ou</i> déplorer pour soi, <i>acc</i>. SOPH. <i>Tr. 153 ;</i><br><b>      3</b> <i>pass. au fut. ant</i>. μάτην ἐμοὶ κεκλαύσεται, AR. <i>Nub. 1436,</i> en vain je pleurerai.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. sbj. 3 sg. poét</i>. κλαίῃσι, OD. <i>8, 523 ; opt. 2 sg. poét</i>. κλαίοισθα, IL. <i>24, 609. Impf. poét</i>. κλαῖον, IL. <i>17, 427 ;</i> OD. <i>1, 363. Impf. itér</i>. κλαίεσκον, IL. <i>8, 364. Fut</i>. κλαύσομαι, IL. <i>22, 87, etc. ;</i> EUR. <i>Cycl. 554 ;</i> AR. <i>Nub. 58, etc. ;</i> DÉM. <i>59, 38 Baiter-Sauppe ; réc</i>. κλαύσω, DH. <i>4, 70, etc. ;</i> THCR. <i>Idyl. 23, 34, etc. Ao</i>. ἔκλαυσα, EUR. <i>Tr. 482, etc. ; 3 sg. poét</i>. κλαῦσε, OD. <i>3, 261. Pf inus. Pass. fut. réc</i>. κλαυσθήσομαι, SPT. <i>Ps. 77, 64. Ao. réc</i>. ἐκλαύσθην, ANTH. <i>App. 341 ;</i> JOS. <i>A.J. 8, 11, 1. Pf</i>. κέκλαυμαι, ESCHL. <i>Ch. 687 ;</i> SOPH. <i>O.R. 1490, etc. ; réc</i>. κέκλαυσμαι, PLUT. <i>M. 115 ;</i> LYC. <i>273. Fut. ant. 3 sg</i>. κεκλαύσεται, AR. <i>Nub. 1436. Moy. ao</i>. ἐκλαυσάμην, SOPH. <i>Tr. 153, etc. ; pf. part</i>. κεκλαυμένος (<i>v. ci-dessus). — Conjug. att</i>. κλάω (<i>non contracte</i>) ESCHL. <i>Sept. 872, etc. ;</i> SOPH. <i>El. 283, etc. ;</i> PLAT. <i>Phil. 48</i> a, <i>etc. Impf</i>. ἔκλαον, SOPH. <i>Tr. 905, etc. ;</i> ISOCR. <i>17, 18 Baiter-Sauppe. Fut</i>. κλαύσομαι, <i>seul. us. chez les Trag. et les Com. ; en prose att</i>. κλαήσω, DÉM. <i>19, 310 Baiter-Sauppe, etc</i>.<br><span><b>Étym</b>. <i>p</i>. *κλάϝϳω ; <i>p.-ê. R. indo-europ</i>. *kleh₂u-, pleurer, <i>ou pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλασις - κλάσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2801":"<h1>klasma</h1>\n<p>Strong n° 2801 <i>Prononciation [klas'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un fragment, une pièce brisée\n<ol type=\"a\">\n<li>restants de nourriture</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλάσμα, ατος (τὸ)</b> morceau brisé, fragment, ANTH. <i>11, 153 ;</i> PLUT. <i>T. Gracch. 19 ;</i> NT. <i>Marc. 6, 43, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att</i>. CIA. <i>2, 678 b, 33 (378/366 av. J.C.) ; v. Meisterh. p. 149, 6</i>.<br><span><b>Étym</b>. κλάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλασμα - κλάσμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G2802":"<h1>Klauda</h1>\n<p>Strong n° 2802 <i>Prononciation [klow'-day]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Clauda = « boiteux »\n<ol><li>petite île proche du Cap de Malte, sur la côte sud de Crète, appelée aussi Cauda et Gaudos, Claudanesa, Gaudonesi, Gozzo.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κλαυδα - Καῦδα</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2803":"<h1>Klaudia</h1>\n<p>Strong n° 2803 <i>Prononciation [klow-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Claudia = « boiteuse »\n<ol><li>une femme chrétienne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κλαυδία, ας (ἡ)</b> = <i>lat</i>. Claudia, <i>n. de f. rom</i>. PLUT. <i>T. Gracch. 4</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κλαυδια - Κλαυδία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2804":"<h1>Klaudios</h1>\n<p>Strong n° 2804 <i>Prononciation [klow'-dee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Claude (Angl. Claudius) = « boiteux »\n<ol>\n<li>Claudius Caesar, le nom du quatrième empereur Romain, qui vint au pouvoir en 41 ap. J.C et fut empoisonné par son épouse Agrippine en 54.</li>\n<li>Claudius Lysias un tribun de la cohorte Romaine qui sauva Paul de la foule à Jérusalem</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κλαύδιος, ου (ὁ)</b> = <i>lat</i>. Claudius, <i>n. d’h. rom</i>. PLUT. <i>T. Gracch. 4, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κλαυδιος - Κλαύδιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G2805":"<h1>klauthmos</h1>\n<p>Strong n° 2805 <i>Prononciation [klowth-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>des pleurs, lamentation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλαυθμός, οῦ (ὁ)</b> lamentation, gémissement, IL. <i>24, 717 ;</i> OD. <i>4, 212, etc. ;</i> ESCHL. <i>Ag. 1553 ; en parl. d’enfants,</i> ARSTT. <i>Pol. 7, 17, etc</i>.<br><span><b>Étym</b>. κλαίω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλαυθμος - κλαυθμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2806":"<h1>klao</h1>\n<p>Strong n° 2806 <i>Prononciation [klah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>briser, rompre\n<ol type=\"a\">\n<li>utilisé dans le N.T. pour rompre le pain de la communion</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κλάω-ῶ</b> <span>(<i>impf</i>. ἔκλων, <i>f</i>. κλάσω <span>[ᾰ]</span>, <i>ao</i>. ἔκλασα <span>[ᾰσ]</span>, <i>pf. inus. ; pass. f</i>. κλασθήσομαι, <i>ao</i>. ἐκλάσθην, <i>pf</i>. κέκλασμαι)</span> briser, <i>d’où :</i><br><b>      1</b> <i>propr</i>. briser, rompre, casser, <i>particul. en parl. de branches d’arbres, de jeunes pousses,</i> OD. <i>6, 128 ; du bois d’une flèche,</i> IL. <i>11, 584 ; de branches ou de pousses de vigne,</i> TH. <i>C.P. 1, 15, 1 ;</i> LGS <i>3, 29 ; fig</i>. τὴν ἐλπίδα, JOS. <i>B.J. 3, 7, 13,</i> briser l’espérance ; <i>part. pf. pass</i>. brisé, affaibli (par l’ivresse, <i>etc</i>.) PLUT. <i>M. 596</i> c ;<br><b>      2</b> infléchir, courber, <i>d’où au pass</i>. s’infléchir ; <i>au propre en parl. de routes,</i> PLUT. <i>M. 968 ; du cours d’un fleuve,</i> PLUT. <i>M. 747, etc. ;</i> ἡ κεκλασμένη (<i>s.-e</i>. γραμμή) ARSTT. <i>Phys. 5, 4, 15,</i> ligne brisée ; <i>en parl. de la réfraction de la lumière, des rayons visuels,</i> ARSTT. <i>Meteor. 3, 6, 4, etc. ; fig. part. pf. pass</i>. qui s’infléchit doucement, qui prend de molles inflexions, <i>en parl. de la voix,</i> HPC. <i>1229</i> e ; DC. <i>79, 13 ; du rythme,</i> LGN <i>40 ; de chants,</i> PLUT. <i>M. 1138</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. poét. 3 sg</i>. κλάσσε, THCR. <i>Idyl. 25, 147. Moy. ao. 3 sg</i>. κλάσσατο, ANTH. <i>7, 124</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span></span><br><br>\n➁ <b>κλάω</b>, <i>v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλαω - κλάω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 14 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (3)</li>\n<li>Luc (2)</li>\n<li>Actes (4)</li>\n<li>1 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G2807":"<h1>kleis</h1>\n<p>Strong n° 2807 <i>Prononciation [klice]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une clef\n<ol type=\"a\">\n<li>le gardien des clefs avait le pouvoir d'ouvrir et de fermer</li>\n<li>métaph. dans le N.T., possède une idée de pouvoir et d'autorité de diverses sortes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλείς, κλειδός (ἡ)</b> tout ce qui sert à fermer, <i>particul. :</i><br><b>   I</b> instrument pour fermer une porte, <i>càd. :</i><br><b>      1</b> verrou, <i>qu’on manœuvrait même du dehors, à l’aide de deux courroies, dont l’une servait à fermer et l’autre à ouvrir la porte,</i> IL. <i>14, 168 ;</i> OD. <i>1, 442 ; 4, 802, etc. ;</i><br><b>      2</b> sorte de crochet, <i>à l’aide duquel on pouvait du dehors soulever la barre</i> (ὀχεύς) <i>qui retenait la porte,</i> OD. <i>21, 6, etc. ;</i><br><b>      3</b> clef, PLUT. <i>M. 43</i> c, <i>526</i> e ;<br><b>      4</b> agrafe, <i>particul</i>. crochet d’une agrafe, OD. <i>18, 294 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> clavicule, <i>os en forme de clef, formant le collet de la poitrine,</i> IL. <i>5, 146 ; 8, 325 ;</i> AND. <i>9, 5 ;</i> DÉM. <i>247, 11 ;</i> ARSTT. <i>H.A. 3, 3, 7 ; au pl</i>. IL. <i>22, 324 ; particul</i>. gorge du thon, <i>partie délicate et recherchée (cf</i>. κλειδίον) ARISTOPHON (ATH. <i>303</i> a) ;<br><b>      2</b> passe, détroit, <i>sorte de clef qui donne accès dans une mer,</i> EUR. <i>Med. 213 ;</i><br><b>      3</b> <i>p. anal. avec le verrou d’une porte assujetti par une courroie,</i> tolet, <i>cheville à laquelle était fixée la rame au moyen d’une courroie, pl</i>. IL. <i>16, 170 ;</i> OD. <i>2, 419, etc. ;</i><br><b>      4</b> crochet pour maîtriser les porcs, ANTH. <i>6, 306</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc</i>. κλεῖν, DÉM. <i>247, 11, etc. ;</i> κλεῖδα, PLUT. <i>Artax. 9 ; plur</i>. κλεῖδες <i>ou</i> κλεῖς, ARSTT. <i>H.A. 3, 7 ; acc</i>. κλεῖδας, ARSTT. <i>H.A. 3, 2 et 3, ou</i> κλεῖς, ARSTT. <i>H.A. 3, 3 ; dat</i>. κλεισίν, PLAT. <i>Ax. 371. — Ion. et homér</i>. κληΐς, ῗδος, ῗδα, IL. <i>14, 168, etc. ;</i> OD. <i>1, 442, etc. ; dat</i>. κληῗσιν, IL. <i>16, 170 ;</i> OD. <i>8, 37 ; épq</i>. κληΐδεσσιν, OD. <i>12, 215 ; plur. nom</i>. κληῗδες, HDT. <i>5, 108. Anc. att</i>. κλῄς, ESCHL. <i>fr. 293 ;</i> SOPH. <i>O.C. 1052 ;</i> -ῃδός, SOPH. <i>Tr. 1035 ;</i> -ῇδα, EUR. <i>Med. 212, 661 ; plur. nom</i>. -ῇδες, EUR. <i>Bacch. 448 ; gén</i>. -ῃδῶν, <i>acc</i>. -ῇδας, ESCHL. <i>Eum. 827 ;</i> EUR. <i>Tr. 257, Med. 1314 ; de même dans une inscr. att</i>. κληΐς, CIA. <i>2, 675, 44 (après 403 av. J.C.) ; ttef. dès le 4<sup>e</sup> siècle av. J.C</i>. κλείς <i>apparaît dans les inscr. att</i>. CIA. <i>2, 675 z, 47 ; 678 b, 54 (378/366 av. J.C.) ; etc. ; v. Meisterh. p. 28, 3 ; cf</i>. κλείω. <i>Dor</i>. κλαΐς, κλαῗδος <span>[ᾱ]</span> SIM. <i>fr. 82 ;</i> PD. <i>P. 9, 69 ; acc</i>. κλαῗδα <i>ou</i> κλᾷδα, CALL. <i>Cer. 45 ; plur. nom</i>. κλαῗδες, PD. <i>P. 9, 69 ; acc</i>. κλαῗδας, PD. <i>P. 8, 4 ; dor</i>. κλᾴξ, THCR. <i>Idyl. 15, 33</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *kleh₂u-, serrure ; <i>cf. lat</i>. clāvus, clāvis.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλεις - κλείς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G2808":"<h1>kleio</h1>\n<p>Strong n° 2808 <i>Prononciation [kli'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fermer, clore</li>\n<li>métaph.\n<ol type=\"a\">\n<li>les cieux fermés qui refusent la pluie</li>\n<li>se fermer à la compassion comme une chose inaccessible, être dépourvu de pitié envers d'autres</li>\n<li>obstruer l'entrée au royaume des cieux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κλείω</b>, <i>anc. att</i>. <b>κλῄω</b> <span>(<i>f</i>. κλείσω, <i>ao</i>. ἔκλεισα, <i>pf</i>. κέκλεικα, <i>pl.q.pf</i>. ἐκεκλείκειν ; <i>pass. f</i>. κλεισθήσομαι, <i>ao</i>. ἐκλείσθην, <i>pf</i>. κέκλειμαι <i>ou</i> κέκλεισμαι, <i>pl.q.pf</i>. ἐκεκλείμην)</span><br><b>      1</b> fermer avec une barre, un verrou <i>ou</i> une clef, <i>avec l’acc. de l’objet qu’on ferme :</i> θύρας, OD. <i>21, 387 ;</i> πύλας, EUR. <i>H.f. 997 ;</i> PLAT. <i>Rsp. 560</i> c, fermer une porte ; <i>p. anal</i>. βλέφαρον, SOPH. <i>fr. 636 ;</i> στόμα, EUR. <i>Ph. 872 ;</i> AR. <i>Eq. 1316,</i> fermer la paupière, la bouche ; <i>fig</i>. DÉM. <i>778, 12 ; avec l’acc. de l’objet avec lequel on ferme :</i> ὀχῆας, OD. <i>24, 166,</i> mettre la barre à une porte ; <i>p. suite,</i> claveter, caler, fixer au moyen d’une clavette, ATHÉNÉE MÉC. ;<br><b>      2</b> clore, fermer : βόσπορον, ESCHL. <i>Pers. 723,</i> un bosphore ;<br><b>      3</b> enfermer : πόλιν πύργων μηχανῇ, ESCHL. <i>Suppl. 956 ; cf</i>. ANTH. <i>9, 62,</i> une ville d’une enceinte de tours ; χέρας βρόχοισι, EUR. <i>Andr. 503,</i> enfermer les mains dans des liens ; <i>fig</i>. ὅρκοις κεκλῄμεθα, EUR. <i>Hel. 977,</i> nous sommes liés par des serments.<br><span><b><span class=\"arrow\"></span></b> <i>F. dor</i>. κλαξῶ, THCR. <i>Idyl. 6, 32. Anc. att</i>. κληΐω, κλῄω ; <i>au 4<sup>e</sup> siècle av. J.C</i>. κλείω <i>apparaît dans une inscr. att</i>. κλειομένην, CIA. <i>2, 1054, 65 (347 av. J.C.) ; v. Meisterh. p. 28, 3</i>.<br><span><b>Étym</b>. κλείς.</span></span><br><br>\n➁ <b>κλείω</b> (<i>seul. prés. et impf. act. et prés. pass</i>.) :<br><b>      1</b> vanter, célébrer : τινά, OD. <i>1, 338, etc. ;</i> τι, AR. <i>Pax 779,</i> qqn <i>ou</i> qqe ch. ; <i>au pass</i>. être célébré A. RH. <i>1, 238 ;</i><br><b>      2</b> appeler, nommer, ORPH. <i>Lith. 193 ;</i> OPP. <i>H. 5, 536</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf</i>. κλεῖον, ORPH. <i>Lith. 193 ;</i> A. RH. <i>2, 163</i>.<br><span><b>Étym</b>. <i>cf</i>. κλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλειω - κλείω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G2809":"<h1>klemma</h1>\n<p>Strong n° 2809 <i>Prononciation [klem'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chose volée, vol, larcin</li>\n<li>l'action du voleur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλέμμα, ατος (τὸ)</b> <span>[ᾰ]</span><br><b>      1</b> chose volée, ARSTT. <i>Probl. 29, 14, 1 ;</i><br><b>      2</b> vol, larcin, EUR. <i>Hec. 618 ;</i> PLAT. <i>Leg. 857</i> b, <i>etc. ; fig</i>. EL. <i>N.A. 1, 2 ;</i><br><b>      3</b> <i>p. ext</i>. fourberie, ruse, DÉM. <i>236, 2 ;</i> ESCHN. <i>68, 1 et 10 ; particul</i>. ruse de guerre, stratagème, THC. <i>5, 9</i>.<br><span><b>Étym</b>. κλέπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλεμμα - κλέμμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2810":"<h1>Kleopas</h1>\n<p>Strong n° 2810 <i>Prononciation [kleh-op'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cléopas (Angl. Cleopas) = « d'un père renommé »\n<ol><li>un des deux disciples qui allaient à Emmaüs le jour de la résurrection</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κλεοπας - Κλεοπᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2811":"<h1>kleos</h1>\n<p>Strong n° 2811 <i>Prononciation [kleh'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rumeur, rapport</li>\n<li>gloire, louange, renommée, gloire humaine</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλέος (τὸ)</b> (<i>us. seul. aux nom. et acc. sg. et aux nom. et acc. plur</i>. κλέα <span>[ᾰ]</span> <i>v. ci-dessous</i>) :<br><b>   I</b> bruit, nouvelle qui se répand, IL. <i>2, 584, etc. ;</i> OD. <i>1, 283, etc. ;</i> ESCHL. <i>Ag. 488 ;</i> SOPH. <i>Ph. 251 ;</i> κλέος φόνου, OD. <i>23, 137,</i> bruit d’un meurtre ; κλ. Ἀχαιῶν, IL. <i>11, 227,</i> bruit de l’armement des Grecs ; σὸν κλέος, OD. <i>13, 415,</i> nouvelles de toi ; <i>particul</i>. bruit sans fondement, <i>p. opp. à</i> nouvelle certaine, IL. <i>2, 486 ;</i> ESCHL. <i>Ag. 487 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> <i>en b. part,</i> bonne renommée, <i>d’où</i> gloire, <i>joint à</i> ἔπαινος, PLAT. <i>Leg. 663</i> a ; <i>à</i> τιμή, EUR. <i>Andr. 774 ; dans Hom., Pind. et les Trag. d’ord. avec un adj</i>. (κλ. ἐσθλόν, IL. <i>5, 3 ;</i> εὐρύ, OD. <i>1, 344 ;</i> μέγα, IL. <i>10, 212 ;</i> EUR. <i>El. 1074 ;</i> ὑψηλόν, PD. <i>P. 3, 196 ;</i> ὑπέρτατον, SOPH. <i>Ph. 1347) ; en prose</i> (κλ. μέγα, HDT. <i>7, 220 ;</i> LYS. <i>190, 40 ;</i> καλόν, PLAT. <i>Leg. 625</i> a ; ἀείμνηστον, XÉN. <i>Cyn. 1, 6 ;</i> ἀθάνατον, PLAT. <i>Conv. 208</i> c) ; <i>souv. aussi abs</i>. IL. <i>4, 197 ; 7, 91, etc. ;</i> κλέος εἶναί τινι, IL. <i>22, 514,</i> être une gloire pour qqn ; κλέος οὐρανὸν εὐρὺν ἱκάνει, OD. <i>8, 74 ; 9, 20, etc</i>. sa gloire va jusqu’au vaste ciel ; κλ. ἑλέσθαι, εὑρέσθαι, PD. <i>O. 9, 154 ;</i> λαϐεῖν, SOPH. <i>Ph. 1347 ;</i> φέρεσθαι, SOPH. <i>El. 60,</i> obtenir, rencontrer, recueillir de la gloire ; <i>en prose,</i> κλέος ἔχειν, THC. <i>1, 25,</i> être renommé ; <i>avec</i> κλέος <i>pour sujet,</i> XÉN. <i>Cyn. 1, 6 ; avec le gén. de la chose qui procure de la gloire :</i> κλ. ἀγῶνος, SOPH. <i>fr. 675,</i> la gloire du combat ; <i>au pl</i>. actions glorieuses, hauts faits, IL. <i>9, 189, 524 ;</i> OD. <i>8, 73 ;</i><br><b>      2</b> <i>en mauv. part,</i> mauvaise réputation, PD. <i>N. 8, 62 ;</i> EUR. <i>Hel. 135</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur. épq</i>. κλεῖα, HÉS. <i>Th. 100</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ḱleu-s-, mot, renommée, <i>de la</i> R. *ḱleu-, entendre ; <i>cf</i>. κλέω, κλύω, <i>sscr</i>. śrávas-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλεος - κλέος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2812":"<h1>kleptes</h1>\n<p>Strong n° 2812 <i>Prononciation [klep'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui détourne, un chapardeur\n<ol type=\"a\">\n<li>le nom est transmis aux faux enseignants, qui n'ont pas soin d'instruire, mais abusent de la confiance pour leur propre gain</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλέπτης, ου (ὁ) :<br>      1</b> voleur, IL. <i>3, 11 ;</i> ESCHL. <i>Pr. 946 ;</i> EUR. <i>I.T. 1026 ;</i> PLAT. <i>Rsp. 344</i> b, <i>etc. ;</i><br><b>      2</b> <i>p. ext</i>. tout homme qui dérobe <i>ou</i> dissimule qqe ch., fourbe, SOPH. <i>Aj. 1135</i>.<br><span><b>Étym</b>. κλέπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλεπτης - κλέπτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote celui qui vole à la dérobée\n<br><br> – est pour celui qui vole ouvertement</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n<li>Jean (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2813":"<h1>klepto</h1>\n<p>Strong n° 2813 <i>Prononciation [klep'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>voler, dérober\n<ol type=\"a\">\n<li>commettre un vol</li>\n<li>emporté par un voleur, pris à la dérobée</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλέπτω</b> <span>(<i>impf</i>. ἔκλεπτον, <i>f</i>. κλέψω, <i>ao</i>. ἔκλεψα, <i>pf</i>. κέκλοφα ; <i>pass. ao</i>. ἐκλέφθην, <i>ao.2</i> ἐκλάπην <span>[ᾰ]</span>, <i>pf</i>. κέκλεμμαι)</span><br><b>   I</b> voler, dérober : τι, HDT. <i>2, 174, etc. ;</i> ESCHL. <i>Pr. 8 ;</i> SOPH. <i>Ph. 1272 ;</i> PLAT. <i>Leg. 857</i> a, <i>etc</i>. qqe ch. ; <i>p. opp. à</i> ἁρπάζω, SOPH. <i>Ph. 644 ;</i> AR. <i>Pl. 372 ; à</i> βιάζομαι, PLAT. <i>Leg. 933</i> e ; <i>à</i> λαμϐάνω, ARSTT. <i>Rhet. 1, 14, 4 ;</i> τι ἔκ τινος, PLAT. <i>Leg. 857</i> b ; <i>ou</i> ἀπό τινος, PLUT. <i>M. 56</i> b, dérober un objet d’un trésor, de qqe ch. ; <i>fig. :</i><br><b>      1</b> d’une manière générale, s’emparer par surprise de : ὄρος, XÉN. <i>An. 5, 6, 9,</i> d’une montagne ; <i>fig</i>. τὴν ἀρχήν, DH. <i>4, 10,</i> du pouvoir ; γάμον δώροις, THCR. <i>Idyl. 22, 151,</i> obtenir une union par surprise et à l’aide de présents ; τὰ τῶν πολεμίων κλ. XÉN. <i>Hipp. 5, 2 ;</i> PLAT. <i>Rsp. 334</i> a, surprendre le secret de l’ennemi ; <i>particul. en parl. de l’intelligence :</i> νόον, IL. <i>14, 217 ;</i> HÉS. <i>Th. 613 ;</i> φρένα, ESCHL. <i>Ch. 854,</i> s’emparer par surprise de l’intelligence, de l’esprit, <i>càd</i>. tromper, abuser ; <i>qqf. en b. part,</i> captiver : κλέπτεται ὁ ἀκροατής, ARSTT. <i>Rhet. 3, 7, 5,</i> l’auditeur est pris, captivé ;<br><b>      2</b> soustraire, dérober : ἐκ τῶν ὀφθαλμῶν κλέπτεταί οἱ ἡ αὐγή, HPC. <i>464, 33,</i> l’éclat de la lumière se dérobe à ses yeux ; κλ. σῶμα ἔκ τινος, EUR. <i>Tr. 958,</i> se laisser glisser du haut de qqe ch. : ἑαυτὸν ἀπό τινος, SYN. <i>Ep. 25,</i> échapper aux mains de qqn ;<br><b>   II</b> cacher, dissimuler : τοῖς ὀνόμασι κλέπτειν τὰ πράγματα, ESCHN. <i>73 fin,</i> dissimuler les choses sous de faux noms ; <i>avec un rég. de pers</i>. ἱππέας κλ. XÉN. <i>Hipp. 5, 2,</i> cacher <i>ou</i> dissimuler une troupe de cavalerie ;<br><b>   III</b> <i>p. suite,</i> faire avec dissimulation, accomplir avec perfidie : κακά, SOPH. <i>Aj. 1137,</i> de mauvais desseins ; μύθους, SOPH. <i>Aj. 188,</i> répandre de mauvaises paroles ; <i>abs. au pass</i>. κλαπέντες ἢ βιασθέντες, PLAT. <i>Rsp. 413</i> b, surpris par la fraude ou contraints par la violence ;<br><b>   IV</b> <i>avec idée de fraude,</i> accomplir secrètement : σφαγάς, SOPH. <i>El. 37,</i> un meurtre ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. κλέψομαι)</span> voler <i>ou</i> dérober à son propre détriment, XÉN. <i>Cyr. 7, 4, 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. part. fém. dor</i>. κλέπτοισα, PD. <i>O. 6, 36. Itér</i>. κλέπτεσκον, HDT. <i>2, 174 ;</i> ANTH. <i>11, 125. Ao. part. dor</i>. κλέψαις, PD. <i>O. 1, 60</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *klep-, voler ; <i>cf</i>. κλέπος, κλοπή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλεπτω - κλέπτω</font>\n<br><br>un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 11 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Romains (3)</li>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2814":"<h1>klema</h1>\n<p>Strong n° 2814 <i>Prononciation [kaly'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>branche tendre et flexible</li>\n<li>spéc. un sarment de vigne</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλῆμα, ατος (τὸ)</b> <span>[ᾰ]</span><br><b>   I</b> tout morceau de bois flexible, <i>particul. :</i><br><b>      1</b> sarment, cep <i>ou</i> branche de vigne, AR. <i>Eccl. 1031 ;</i> PLAT. <i>Rsp. 353</i> a ; TH. <i>H.P. 4, 13, 5 ; fig</i>. τὰ κλήματα τοῦ δήμου, DÉM. (ESCHN. <i>77, 27</i>) les sarments, <i>càd</i>. la force du peuple ; <i>p. suite,</i> baguette des centurions romains faite d’un sarment de vigne, PLUT. <i>Galb. 26 (lat</i>. vitis) ;<br><b>      2</b> jeune pousse, bouture, XÉN. <i>Œc. 19, 8 ;</i> ARSTT. <i>H.A. 5, 18, 10 ;</i><br><b>   II</b> <i>n. de diverses plantes :</i><br><b>      1</b> <i>c</i>. πιτυοῦσσα, DIOSC. <i>4, 166 ;</i><br><b>      2</b> <i>c</i>. πολύγονον, PLIN. <i>H.N. 27, 91</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλημα - κλῆμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (4)</li>\n</ul>\n</td></tr>\n</table>","G2815":"<h1>Klemes</h1>\n<p>Strong n° 2815 <i>Prononciation [klay'-mace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Clément (Angl. Clement) = « doux, miséricordieux, bienveillant »\n<ol><li>compagnon de Paul et apparemment membre de l'église de Philippes. Selon la tradition, ce serait le Clément qui fut évêque de Rome vers la fin du premier siècle</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κλημης - Κλήμης</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2816":"<h1>kleronomeo</h1>\n<p>Strong n° 2816 <i>Prononciation [klay-ron-om-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recevoir un lot, recevoir par tirage au sort\n<ol type=\"a\">\n<li>spéc. recevoir une part d'héritage, recevoir en héritage, obtenir par droit d'héritage</li>\n<li>être un héritier, hériter</li>\n</ol>\n</li>\n<li>recevoir une portion attribuée, recevoir en possession</li>\n<li>devenir participant de, obtenir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κληρονομέω-ῶ</b> <span>(<i>impf</i>. ἐκληρονόμουν, <i>f</i>. κληρονομήσω, <i>ao</i>. ἐκληρονόμησα, <i>pf</i>. κεκληρονόμηκα)</span><br><b>      1</b> recevoir en héritage une part de, hériter de : τινος, DÉM. <i>329, 15 ;</i> IS. <i>47, 10 ;</i> LUC. <i>H. conscr. 20 ;</i> τι, LYCURG. <i>159, 4,</i> de qqe ch. ; <i>fig</i>. τινος, ISOCR. <i>1</i> b ; DÉM. <i>444, 13,</i> de qqe ch. ; <i>p. ext</i>. acquérir, obtenir, <i>en gén. :</i> δόξαν, POL. <i>15, 22, 3,</i> de la gloire ; τὴν βασιλείαν, SPT. <i>1Macc. 2, 10,</i> la royauté ; <i>en mauv. part,</i> SPT. <i>Sir. 6, 1 ;</i><br><b>      2</b> être institué héritier, <i>avec un rég. de pers. :</i> τινα, ANTH. <i>11, 202 ;</i> POSIDON. (ATH. <i>211</i> f) ; PLUT. <i>Syll. 2,</i> de qqn, hériter de qqn ; τινά τινος, DC. <i>45, 47,</i> hériter qqe ch. de qqn ;<br><b>      3</b> laisser pour héritier, <i>acc</i>. SPT. <i>Prov. 13, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy</i>. κληρονομήσομαι <i>au sens pass</i>. LUC. <i>Tox. 22</i>.<br><span><b>Étym</b>. κληρονόμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κληρονομεω - κληρονομέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 17 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>1 Corinthiens (4)</li>\n<li>Galates (2)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2817":"<h1>kleronomia</h1>\n<p>Strong n° 2817 <i>Prononciation [klay-ron-om-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un héritage, propriété reçue (ou à recevoir) par héritage</li>\n<li>ce qui est donné en possession\n<ol type=\"a\">\n<li>l'éternelle bénédiction du royaume de Dieu qui est espérée après le retour de Christ</li>\n<li>la part que chacun aura dans cette bénédiction éternelle</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κληρονομία, ας (ἡ) :<br>      1</b> participation à un héritage, droit d’hérédité, ISOCR. <i>393</i> a ; DÉM. <i>1051, 11 ;</i> ARSTT. <i>Pol. 5, 8 ;</i><br><b>      2</b> <i>p. ext</i>. possession : κληρονομίαν λαμϐάνειν τινός, ARSTT. <i>Nic. 7, 13, 6,</i> prendre possession de qqe ch.<br><span><b>Étym</b>. κληρονόμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κληρονομια - κληρονομία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2818":"<h1>kleronomos</h1>\n<p>Strong n° 2818 <i>Prononciation [klay-ron-om'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui reçoit par lot, un héritier\n<ol type=\"a\">\n<li>un héritier</li>\n<li>dans l'usage Messianique, celui qui reçoit la possession attribuée par droit de descendance</li>\n</ol>\n</li>\n<li>celui qui a acquis ou obtenu la portion qui lui est allouée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κληρο·νόμος, ου (ὁ, ἡ)</b> héritier, héritière : τινός, de qqn, PLAT. <i>Leg. 923</i> e ; <i>ou</i> de qqe ch. LYS. <i>907, 5 ;</i> ISOCR. <i>386</i> b ; <i>fig</i>. τῆς εὐνοίας, ISOCR. <i>109</i> e ; τῆς ἀτιμίας, DÉM. <i>603 fin,</i> héritier de la bienveillance, du déshonneur ; κληρονόμον τινὰ καθιστάναι, ISOCR. <i>386</i> b ; DÉM. <i>603 fin,</i> instituer qqn héritier ; καταλείπειν, ISOCR. <i>109</i> e ; ἀπολείπειν, PLUT. <i>Rom. 5,</i> laisser pour héritier ; γράφειν, ANTH. <i>11, 171,</i> inscrire pour héritier.<br><span><b>Étym</b>. κλῆρος, νέμω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κληρονομος - κληρονόμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 14 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (4)</li>\n<li>Galates (3)</li>\n<li>Tite (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2819":"<h1>kleros</h1>\n<p>Strong n° 2819 <i>Prononciation [klay'-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>objet utilisé pour le tirage au sort, qui était soit un caillou, ou un tesson, ou une pièce de bois\n<ol type=\"a\">\n<li>les lots de plusieurs personnes concernées, qui mettaient leurs noms dans un vase, qui était secoué, et le premier nom qui tombait au sol était choisi</li>\n</ol>\n</li>\n<li>ce qui est alloué par tirage, portion attribuée\n<ol type=\"a\">\n<li>une partie du ministère commun aux apôtres</li>\n<li>utilisé pour celui qui a reçu comme part le salut éternel\n<ol>\n<li>le salut lui-même</li>\n<li>le salut éternel assigné aux saints par Dieu</li>\n</ol>\n</li>\n<li>des personnes\n<ol>\n<li>ceux à qui ont été assignés le soin et la charge des églises chrétiennes, dont l'administration est leur partage</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κλῆρος, ου (ὁ) :<br>   I. 1</b> objet dont on se sert pour tirer au sort, <i>primit. petites pierres, cailloux, petits morceaux de bois qu’on déposait dans un casque, postér. dans un vase où on les agitait avant de tirer :</i> ἐν κλήρους <i>ou</i> ἐπὶ κλήρους ἐϐάλοντο, IL. <i>23, 352 ;</i> OD. <i>14, 209,</i> ils jetèrent les sorts (dans le casque) ; κλῆρον καθιέναι, SOPH. <i>Aj. 1285,</i> jeter le sort (dans le casque <i>ou</i> dans l’urne) ; κλήρους ἐν κυνέῃ πάλλειν, IL. <i>3, 316, etc</i>. agiter les sorts dans un casque ; ἐξέθορε κλῆρος κυνέης, IL. <i>7, 182,</i> le sort est sorti du casque ; ἐκ κλῆρος ὄρουσεν, IL. <i>3, 325,</i> le sort est sorti ; κλήρῳ λαχεῖν, IL. <i>24, 400, etc</i>. obtenir par le sort ; κλάροισι θεοπροπέων, PD. <i>P. 4, 338,</i> prédisant l’avenir au moyen de sorts ;<br><b>      2</b> <i>p. suite,</i> tirage au sort, attribution par le sort (d’une fonction, <i>etc</i>.) EUR. <i>I.A. 1198 ; p. opp. à</i> χειροτονία, <i>traduct. du lat</i>. sortitio, PLUT. <i>Æmil. 10 ;</i><br><b>   II</b> ce qu’on obtient par le sort, lot, part, <i>particul. :</i><br><b>      1</b> part d’héritage, <i>d’où</i> héritage, PLAT. <i>Leg. 923 b et c ;</i> IS. <i>84, 23, etc. ;</i> καταφαγεῖν κλῆρον, HIPPON. (ATH. <i>304</i> b) dévorer un héritage ;<br><b>      2</b> bien, domaine, IL. <i>15, 498 ;</i> OD. <i>14, 64 ; particul</i>. lot de terre assigné à des colons (<i>cf</i>. κληρουχία) HDT. <i>2, 109 ;</i> THC. <i>3, 50 ;</i> PLAT. <i>Leg. 741</i> b, <i>etc. ; d’où en gén</i>. pays, contrée possédée <i>ou</i> habitée par qqn, ESCHL. <i>Pers. 899, etc. ;</i> EUR. <i>Her. 876 ;</i> NIC. (ATH. <i>683</i> a) ; CALL. <i>Del. 281, etc. ;</i><br><b>      3</b> lot attribué à une église, <i>d’où</i> à un prêtre, <i>et, p. suite,</i> fonction de prêtre, clergé, ECCL.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κλᾶρος, PD. <i>O. 13, 87, cf. ci-dessus, etc. ;</i> CALL. <i>L. Pall. 142</i>.<br><span><b>Étym</b>. <i>p.-ê. pré-grec</i>.</span></span><br><br>\n➁ <b>κλῆρος, ου (ὁ)</b> insecte qui ronge les ruches d’abeilles, ARSTT. <i>H.A. 8, 27, 2, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κληρος - κλῆρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (6)</li>\n<li>Colossiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2820":"<h1>kleroo</h1>\n<p>Strong n° 2820 <i>Prononciation [klay-ro-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déterminer par tirage, désigner par le sort</li>\n<li>choisir par le hasard</li>\n<li>accorder, répartir, assigner par tirage</li>\n<li>dans le N.T : devenir héritier, avoir en héritage, en possession privée</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κληρόω-ῶ</b> (<i>seul. prés. et ao</i>. ἐκλήρωσα ; <i>pass. seul. pf</i>. κεκλήρωμαι) :<br><b>   I</b> tirer au sort, <i>abs</i>. PLAT. <i>Leg. 759</i> c ;<br><b>   II</b> <i>p. suite :</i><br><b>      1</b> désigner par la voie du sort, <i>acc</i>. POL. <i>6, 20, 2 ; particul</i>. désigner pour une fonction par la voie du sort : τινα, LUC. <i>Herm. 39,</i> qqn ; τινα ἐπί τινι, HDT. <i>1, 94,</i> qqn pour qqe ch. ; <i>p. opp. à</i> χειροτονεῖν <i>ou à</i> αἱρεῖσθαι : τὰς ἀρχάς, ISOCR. <i>144</i> a, attribuer les charges par la voie du sort ; <i>au pass</i>. κληροῦσθαι τῶν ἐννέα ἀρχόντων, LYS. <i>169, 24,</i> être désigné par le sort comme l’un des neuf archontes ;<br><b>      2</b> <i>en gén</i>. assigner par la voie du sort : τινά <i>ou</i> τί τινι, PD. <i>O. 8, 19 ;</i> THC. <i>6, 42,</i> qqn <i>ou</i> qqe ch. à qqn ; <i>avec l’idée de sort pour sujet :</i> οὓς ἐκλήρωσεν πάλος, EUR. <i>Ion 416,</i> ceux que le sort a désignés ;<br><b>      3</b> <i>poét</i>. κλ. ὀμφάν, EUR. <i>Ion 908,</i> rendre un oracle par la voie du sort ;<br><b>   III</b> désigner pour héritier, <i>acc</i>. SPT. <i>Esaï. 17, 11 ;</i><br><b><i>Moy</i>. κληροῦμαι</b> <span>(<i>impf</i>. ἐκληρούμην, <i>f</i>. κληρώσομαι, <i>ao</i>. ἐκληρωσάμην)</span><br><b>      1</b> tirer au sort, ESCHL. <i>Sept. 53 ;</i> PLAT. <i>Leg. 741</i> b ; <i>p. suite,</i> se faire attribuer par la voie du sort : τι, ESCHL. <i>26, 36 ;</i> XÉN. <i>Cyr. 1, 6, 19 ;</i> τινος, DÉM. <i>1318, 16,</i> qqe ch. ;<br><b>      2</b> <i>p. suite, au pf</i>. κεκληρῶσθαι, avoir obtenu par la voie du sort, <i>d’où</i> être par la voie du sort en possession de, <i>avec l’inf</i>. posséder par la voie du sort le droit de, LUC. <i>Luct. 2</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κλαρόω <span>[ᾱ]</span> PD. <i>O. 8, 19</i>.<br><span><b>Étym</b>. κλῆρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κληροω - κληρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2821":"<h1>klesis</h1>\n<p>Strong n° 2821 <i>Prononciation [klay'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un appel, une vocation</li>\n<li>un appel, une invitation\n<ol type=\"a\">\n<li>à une fête</li>\n<li>à l'invitation divine à recevoir le salut de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κλῆσις, εως (ἡ) :<br>   I. 1</b> action d’appeler à soi, XÉN. <i>Cyr. 3, 2, 14,</i> PLAT. <i>Conv. 172</i> a ;<br><b>      2</b> action d’invoquer : τῶν θεῶν, MÉN. RHÉT. <i>9, 132 W.,</i> les dieux ; <i>abs</i>. action d’appeler à son secours, POL. <i>2, 50, 7 ;</i><br><b>      3</b> action d’inviter, de convier, invitation (à une fête, à un repas, <i>etc</i>.) XÉN. <i>Conv. 1, 7 ;</i> DL. <i>4, 48 ;</i> PLUT. <i>Per. 7 ;</i><br><b>      4</b> assignation, citation devant un tribunal, XÉN. <i>Hell. 1, 7, 13 ;</i> DÉM. <i>640, 25 ;</i> AR. <i>Nub. 1189, etc. ;</i><br><b>      5</b> convocation de citoyens, <i>d’où</i> répartition par classes, DH. <i>4, 18 (cf. lat</i>. classis) ;<br><b>   II</b> action de nommer, <i>d’où :</i><br><b>      1</b> nom, dénomination, PLAT. <i>Pol. 262</i> d, <i>287</i> e ;<br><b>      2</b> désignation (de masculin <i>ou</i> de féminin, <i>en parl. des noms</i>) ARSTT. <i>Soph. el. 14, 4 ;</i><br><b>      3</b> nominatif (<i>p. opp. à</i> αἱ πτώσεις, les cas de la déclinaison) ARSTT. <i>An. pr. 1, 36, 7</i>.<br><span><b>Étym</b>. καλέω.</span><br><br>\n➁ <b>κλῇσις, εως (ἡ)</b> <i>att. c</i>. κλεῖσις, THC. <i>2, 94, etc</i>.<br><br>\n<b>κλεῖσις, εως (ἡ) :<br>      1</b> action de fermer, fermeture, THC. <i>2, 94 ; 7, 70 ;</i><br><b>      2</b> <i>t. techn</i>. déclic, batterie (d’une machine de jet) HÉRON.<br><span><b><span class=\"arrow\"></span></b> <i>Att</i>. κλῇσις, THC. <i>l. c</i>.<br><span><b>Étym</b>. κλείω, κλῄω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλησις - κλῆσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 8 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2822":"<h1>kletos</h1>\n<p>Strong n° 2822 <i>Prononciation [klay-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appelé, invité (à un banquet)\n<ol type=\"a\">\n<li>invité (par Dieu dans la proclamation de l'Evangile) à obtenir le salut éternel dans le royaume à travers Christ</li>\n<li>appelé à une fonction, avoir une charge\n<ol>\n<li>divinement sélectionné et désigné</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλητός, ή, όν</b>, appelé, <i>càd. :</i><br><b>      1</b> convié, invité, ESCHN. <i>50, 1 ;</i> EL. <i>N.A. 11, 22 ; d’où</i> bienvenu, OD. <i>17, 386 ;</i><br><b>      2</b> convoqué <i>ou</i> appelé nominativement, <i>càd</i>. choisi, IL. <i>9, 165</i>.<br><span><b>Étym</b>. <i>vb. de</i> καλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλητος - κλητός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (3)</li>\n<li>Jude (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2823":"<h1>klibanos</h1>\n<p>Strong n° 2823 <i>Prononciation [klib'-an-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un « clibanus », four familial privé, était une grande jarre en terre, et transportable ; après l'avoir chauffée, on appliquait contre les parois de la jarre les galettes, qui, cuites de cette manière étaient très minces.</li>\n<li>un fourneau, un four</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλίϐανος</b>, <i>c</i>. κρίϐανος.<br><br>\n<b>κρίϐανος, ου (ὁ)</b> <span>[ῑᾰ]</span><br><b>      1</b> four à griller l’orge ; <i>p. ext</i>. four de campagne, tourtière, HDT. <i>2, 92 ;</i> ESCHL. (ATH. <i>375</i> e) ; AR. <i>Vesp. 1153, etc. ;</i><br><b>      2</b> vase en forme d’entonnoir pour tirer de l’eau d’un puits, STR. <i>754 ;</i><br><b>      3</b> trou de rocher, EL. <i>N.A. 2, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Att</i>. κρίϐανος, AR. <i>l. c. ;</i> PAUS. <i>9, 39, etc. ; ion. et réc</i>. κλίϐανος, HDT. <i>l. c. ;</i> DS. <i>2, 49 ;</i> STR. <i>754, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλιβανος - κλίβανος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2824":"<h1>klima</h1>\n<p>Strong n° 2824 <i>Prononciation [klee'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une inclinaison, une pente, une déclivité</li>\n<li>l'inclinaison de la terre de l'équateur vers les pôles, une zone</li>\n<li>une portion de territoire, une région</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλίμα, ατος (τὸ)</b> <span>[ῐ]</span><br><b>   I</b> <i>au pr. :</i><br><b>      1</b> l’inclinaison, pente (du sol, d’une montagne, <i>etc</i>. SPT. <i>2Esdr. 12, 36, etc</i>.) ;<br><b>      2</b> <i>particul</i>. inclinaison de la terre vers le pôle à partir de l’équateur, <i>d’où</i> climat, région, zone géographique, POL. <i>7, 6, 1, etc. ;</i> DH. <i>1, 9 ;</i> ATH. <i>523</i> e ;<br><b>   II</b> <i>fig</i>. inclination, penchant, ARR. <i>Epict. 2, 15, 20</i>.<br><span><b>Étym</b>. κλίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλιμα - κλίμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT).\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G2825":"<h1>kline</h1>\n<p>Strong n° 2825 <i>Prononciation [klee'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un petit lit, une couche</li>\n<li>un divan sur lequel on prend le repas</li>\n<li>une litière sur lequel un malade est transporté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλίνη, ης (ἡ)</b> <span>[ῑ]</span><br><b>   I</b> lit, <i>càd. :</i><br><b>      1</b> couche, EUR. <i>Hec. 1150 ;</i> AR. <i>Pl. 540 ;</i> ISOCR. <i>389</i> c ; PLUT. <i>M. 128</i> b ;<br><b>      2</b> lit de table, HDT. <i>9, 16 ;</i> XÉN. <i>Cyr. 8, 2, 6 ;</i> PLAT. <i>Conv. 217</i> d ; AR. <i>Ach. 1090 ;</i><br><b>   II</b> bière pour les morts, PLAT. <i>Leg. 947</i> b ; ANTH. <i>11, 92</i>.<br><span><b>Étym</b>. κλίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλινη - κλίνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2826":"<h1>klinidion</h1>\n<p>Strong n° 2826 <i>Prononciation [klin-id'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un petit lit, une couche, une civière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλινίδιον, ου (τὸ)</b> <span>[ῑῐδ]</span> petit lit, AR. <i>Lys. 916 ;</i> PLUT. <i>M. 781</i> e, <i>etc</i>.<br><span><b>Étym</b>. <i>dim. de</i> κλίνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλινιδιον - κλινίδιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2827":"<h1>klino</h1>\n<p>Strong n° 2827 <i>Prononciation [klee'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>trans.\n<ol type=\"a\">\n<li>incliner, courber</li>\n<li>faire tomber, faire fuir</li>\n<li>reposer\n<ol>\n<li>dans un lieu pour le repos</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>intrans.\n<ol type=\"a\">\n<li>baisser, décliner\n<ol>\n<li>le déclin du jour</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλίνω</b> <span>[ῑ]</span> <span>(<i>f</i>. κλινῶ <span>[ῐ]</span>, <i>ao</i>. ἔκλινα <span>[ῑ]</span>, <i>pf</i>. κέκλικα <span>[ῐ]</span> ; <i>pass. f</i>. κλιθήσομαι, <i>ao.1</i> ἐκλίθην <span>[ῐ]</span>, <i>poét</i>. ἐκλίνθην, <i>ao.2</i> ἐκλίνην <span>[ῐ]</span>, <i>pf</i>. κέκλιμαι <span>[ῐ]</span>)</span><br><b>A <i>tr</i>.<br>   I</b> faire pencher, incliner : τάλαντα, IL. <i>19, 223,</i> la balance ; μάστιγα ποτὶ ζυγόν, IL. <i>23, 510,</i> abaisser le fouet vers le joug ; <i>au pass</i>. φύλλα κεκλιμένα, TH. <i>H.P. 3, 9, 2,</i> feuilles pendantes (<i>v. ci-dessous</i> II, 1) ; <i>fig</i>. ἡμέρα κλίνει τε κἀνάγει πάλιν τἀνθρώπεια, SOPH. <i>Aj. 131,</i> un jour abaisse et relève les affaires humaines ; <i>p. suite :</i><br><b>      1</b> appuyer : τι πρός τι, IL. <i>23, 171,</i> une chose sur une autre ; σάκε' ὤμοισι, IL. <i>11, 592,</i> appuyer les boucliers sur l’épaule ; ἀσπίσι κεκλιμένοι, IL. <i>3, 135,</i> s’appuyant sur leurs boucliers ; <i>ou avec</i> ἐν : ἐν δορὶ κεκλιμένος, ARCHIL. <i>2,</i> appuyé sur sa lance ; ξύλα ἐς ἄλληλα κεκλιμένα, HDT. <i>4, 73,</i> pièces de bois inclinées (qui s’appuient) les unes sur les autres ; <i>avec un n. de pers. :</i> κλίνειν τινά, appuyer, soutenir qqn ;<br><b>      2</b> <i>en mauv. part,</i> faire tomber, <i>d’où au pass</i>. s’affaisser, se renverser, tomber : ὑπτία κλίνομαι, SOPH. <i>Ant. 1188,</i> je suis tombée à la renverse ; <i>fig</i>. κέκλιται ἐπὶ γόνυ, ESCHL. <i>Pers. 930,</i> elle est tombée sur les genoux, <i>càd</i>. humiliée ; τὸ τεῖχος ἐκλίνετο, XÉN. <i>Hell. 5, 2, 5,</i> le mur s’écroulait ;<br><b>   II</b> coucher, étendre : τινά, EUR. <i>Alc. 268,</i> qqn ; τινὰ ἐς εὐνήν, EUR. <i>Or. 227,</i> qqn sur un lit ; <i>particul. :</i><br><b>      1</b> étendre à terre, <i>d’où au pass</i>. être étendu à terre, IL. <i>23, 231 ;</i> EUR. <i>Cycl. 545 ;</i> ἐν νεκύεσσι, IL. <i>10, 350,</i> parmi les morts ; παραὶ λεχέεσσι, OD. <i>18, 213,</i> auprès dans un lit ; ἔντεα χθονὶ κέκλιτο, IL. <i>10, 472,</i> les armes étaient étendues à terre ; φύλλα κεκλιμένα, OD. <i>11, 194,</i> feuilles tombées (<i>cf. ci-dessus</i> I, 1) ;<br><b>      2</b> coucher sur un lit de table, <i>d’où au pass</i>. être couché sur un lit de table, être à table, HDT. <i>1, 211 ;</i> EUR. <i>H.f. 956 ;</i><br><b>      3</b> <i>en parl. de lieux, particul. au pf. pass</i>. être situé : νῆσοι αἵθ' ἁλὶ κεκλίαται, OD. <i>4, 608,</i> les îles qui se trouvent dans la mer ; κεκλιμένος (τόπος) πρὸς ἀνατολάς, POL. <i>2, 14, 4 ;</i> εἰς τὰς ἄρκτους, POL. <i>1, 42, 5,</i> endroit situé vers l’orient, vers le nord (<i>propr</i>. vers l’Ourse) ; <i>qqf. en parl. des personnes, pour exprimer l’idée de fixité :</i> Ὀρέσϐιος λίμνῃ κεκλιμένος Κηφισίδι, IL. <i>5, 709,</i> Oresbios établi sur le lac de Kèphisos ; <i>cf</i>. IL. <i>15, 740 ; 16, 68 ;</i> SOPH. <i>Tr. 101 ;</i><br><b>      4</b> coucher en terre, ensevelir, ANTH. <i>7, 493, etc. ;</i> TRIPHIOD. <i>394 ;</i> Ἀλφεοῦ πόρῳ κλιθείς, PD. <i>O. 1, 148,</i> couché, <i>càd</i>. enseveli près du cours de l’Alphée ;<br><b>   III</b> faire plier, faire fléchir, <i>d’où :</i><br><b>      1</b> déplacer : ἐκ τῶν ἀριστερῶν ἐπὶ τὰ δεξιά, PLAT. <i>Tim. 77,</i> de gauche à droite ;<br><b>      2</b> détourner : ὄσσε πάλιν, IL. <i>3, 427,</i> les yeux ; ἅρματα, IL. <i>8, 435,</i> des chars ; <i>au pass</i>. se détourner : ὁ δ' ἐκλίνθη, IL. <i>7, 254,</i> il se détourna (pour esquiver un coup mortel) ; οὐδ' ἔχω πρὸς πότερα κλιθῶ, SOPH. <i>Ant. 1343,</i> je ne sais de quel côté (à droite <i>ou</i> à gauche) je dois me tourner ;<br><b>      3</b> <i>abs</i>. détourner du droit chemin, <i>d’où</i> se détourner, s’égarer, errer, <i>en parl. d’un navire,</i> THGN. <i>854 ;</i><br><b>      4</b> faire reculer, repousser : Τρῶας, Ἀχαιούς, IL. <i>5, 37, etc</i>. les Troyens, les Grecs ; τὴν μάχην, IL. <i>14, 510,</i> donner au combat une autre direction (<i>cf. lat</i>. aciem inclinare) ;<br><b>      5</b> <i>t. de gramm</i>. faire fléchir (un nom, un verbe) <i>càd</i>. modifier la forme du thème suivant la déclinaison, la conjugaison <i>ou</i> l’augment, DYSC. <i>Synt. 68, 27, etc. ;</i><br><b>B <i>intr</i>.<br>      1</b> incliner, pencher : ἐπὶ δόρυ, POL. <i>6, 40, 12,</i> vers la lance, <i>càd</i>. à droite ; ἐπ' ἀσπίδα, POL. <i>3, 115, 9, etc</i>. vers le bouclier, <i>càd</i>. à gauche ; <i>particul. en parl. du temps :</i> κλίνοντος ἡλίου, A. RH. <i>1, 452,</i> le soleil déclinant ; ἡμέρα ἤρξατο κλίνειν, NT. <i>Luc. 9, 12,</i> le jour commença à baisser ; ἅμα τῷ κλῖναι τὸ τρίτον μέρος τῆς νυκτός, POL. <i>3, 93, 7,</i> vers la troisième partie de la nuit (<i>propr</i>. en même temps que penchait, <i>etc.) ; fig</i>. ἡ πόλις ἐπὶ τὸ χεῖρον ἔκλινεν, XÉN. <i>Mem. 3, 5, 13,</i> l’État penchait vers sa ruine ; τῶν πραγμάτων ἐπὶ Ῥωμαίους κεκλικότων, POL. <i>30, 10, 2,</i> la fortune penchant vers les Romains ;<br><b>      2</b> plier, fléchir : πρὸς φυγήν, POL. <i>1, 27, 8,</i> plier et commencer à fuir ;<br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐκλινάμην)</span><br><b>      1</b> s’appuyer contre <i>ou</i> sur : τινι, OD. <i>17, 340,</i> qqe ch. ;<br><b>      2</b> pencher vers son déclin, décliner, <i>en parl. du jour,</i> HDT. <i>3, 114 ;</i> SOPH. <i>fr. 239</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. sbj. 3 sg</i>. κλίνῃσι, IL. <i>19, 233. Pass. ao.2</i> ἐκλίνην <span>[ῐ]</span> EUR. <i>fr. 692 ;</i> HDT. <i>9, 16 ; pf. 3 pl</i>. κεκλίαται, IL. <i>16, 68</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ḱlei-, s’appuyer ; <i>cf. lat</i>. clīnō, <i>all</i>. lehnen.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλινω - κλίνω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (4)</li>\n<li>Jean (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2828":"<h1>klisia</h1>\n<p>Strong n° 2828 <i>Prononciation [klee-see'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une hutte érigée pour passer la nuit</li>\n<li>une tente</li>\n<li>toute chose pour se reposer\n<ol type=\"a\">\n<li>une chaise où on peut s'asseoir et reposer sa tête</li>\n<li>un siège de repos</li>\n</ol>\n</li>\n<li>une compagnie au repos\n<ol type=\"a\">\n<li>une rangée ou un certain nombre de personnes se reposant pour le repas</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλισία, ας (ἡ)</b> <span>[ῐσ]</span><br><b>   I</b> abri pour se coucher, <i>càd. :</i><br><b>      1</b> hutte, cabane en bois, IL. <i>18, 589 ;</i><br><b>      2</b> tente de soldat, baraquement, IL. <i>9, 663, etc. ;</i> OD. <i>8, 501 ;</i> ESCHL. <i>fr. 122 ; particul</i>. baraques <i>ou</i> campements de marins (formant sur le rivage, auprès des vaisseaux, un camp véritable, avec une ἀγορά et des rues) SOPH. <i>Aj. 192, 1407 ;</i><br><b>   II</b> lit, <i>particul. :</i><br><b>      1</b> couche nuptiale, EUR. <i>Alc. 994, I.T. 857 ;</i><br><b>      2</b> lit de table, PD. <i>P. 4, 133 ;</i> ATH. <i>474</i> d ; <i>d’où</i> place sur un lit de table, PLUT. <i>M. 148</i> e, <i>Ant. 59, etc. ; p. suite,</i> rangée de personnes sur des lits de table, tablée, NT. <i>Luc. 9, 14 ;</i><br><b>      3</b> chaise longue, OD. <i>4, 123 ; 19, 55 ;</i><br><b>   III</b> <i>p. ext</i>. manière de se coucher, PLUT. <i>Sert. 26</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κλισίη, IL. OD. <i>ll. cc</i>.<br><span><b>Étym</b>. κλίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλισια - κλισία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2829":"<h1>klope</h1>\n<p>Strong n° 2829 <i>Prononciation [klop-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vol, action du voleur, larcin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλοπή, ῆς (ἡ) :<br>      1</b> vol, larcin, <i>p. opp. à</i> ἁρπαγή, PLAT. <i>Leg. 941</i> b ; <i>joint à</i> ἁρπαγή, ESCHL. <i>Ag. 534 ;</i> κλοπῆς δίκη, PLAT. <i>Leg. 857</i> b, poursuite pour vol ; κλοπῆς γράφεσθαι, ANT. <i>115, 25, ou</i> ὀφλεῖν, ESCHL. <i>Ag. 534 ;</i> AND. <i>10, 20,</i> être poursuivi <i>ou</i> condamné pour vol ; <i>particul</i>. rapt d’une femme, <i>au plur</i>. ESCHL. <i>Ag. 402 ;</i> EUR. <i>Hel. 1176, etc. ;</i><br><b>      2</b> <i>p. ext</i>. toute action furtive <i>ou</i> clandestine : ποδοῖν κλοπὰν ἀρέσθαι, SOPH. <i>Aj. 247,</i> prendre secrètement la fuite ; κλοπῇ ἀφῖγμαι, EUR. <i>Ion 1254,</i> je suis venue furtivement ; <i>p. suite,</i> ruse, dissimulation, fourberie, SOPH. <i>Ph. 1025 ;</i> EUR. <i>H.f. 100 ;</i> surprise d’un poste militaire, XÉN. <i>An. 4, 6, 16</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κλοπά (<i>v. ci-dessus</i>).<br><span><b>Étym</b>. κλέπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλοπη - κλοπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2830":"<h1>kludon</h1>\n<p>Strong n° 2830 <i>Prononciation [kloo'-dohn]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une grande vague déferlante, la houle, une violente agitation de la mer, forte houle</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλύδων, ωνος (ὁ)</b> <span>[ῠ]</span><br><b>   I</b> agitation des flots, flot, vague, OD. <i>12, 421 ;</i> ESCHL. <i>Pr. 429 ;</i> SOPH. <i>O.C. 1686 ;</i> ARSTT. <i>H.A. 5, 16 ;</i> PLUT. <i>Cæs. 38, etc. ; au pl</i>. LYC. <i>474 ;</i> POL. <i>10, 3, 3 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> <i>en parl. du mouvement impétueux d’une troupe de cavaliers,</i> SOPH. <i>El. 733 ;</i><br><b>      2</b> <i>fig</i>. trouble, agitation, mouvement tumultueux, <i>en parl. de malheurs, de guerre, etc</i>. ESCHL. <i>Pers. 599 ;</i> SOPH. <i>O.R. 1527 ;</i> EUR. <i>I.T. 316, etc. ;</i> PLAT. <i>Leg. 758</i> a ; DÉM. <i>442, 18 ;</i> PLUT. <i>Cor. 32, etc</i>.<br><span><b>Étym</b>. *κλύς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλυδων - κλύδων</font>\n<br><br>vient de kluzo (déferler ou se précipiter)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – une vague, suggérant des successions ininterrompues\n<br><br> – une grande vague, une lame, la houle, suggérant volume et étendue. fig. : Application aux mots, à la parole.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G2831":"<h1>kludonizomai</h1>\n<p>Strong n° 2831 <i>Prononciation [kloo-do-nid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être emporté, ballotté par des vagues</li>\n<li>métaph. être agité mentalement (comme les vagues)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κλυδωνίζω</b> <span>[ῠ]</span> ballotter sur <i>ou</i> comme sur les flots, <i>d’où au pass</i>. être ballotté par <i>ou</i> comme par les flots, NT. <i>Eph. 4, 14</i>.<br><span><b>Étym</b>. κλύδων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κλυδωνιζομαι - κλυδωνίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2832":"<h1>Klopas</h1>\n<p>Strong n° 2832 <i>Prononciation [klo-pas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Clopas (Angl. Cleophas) = « mes échanges »\n<ol><li>le père de Jacques le Mineur, l'époux de Marie la sœur de la mère de Jésus, et d'après Hégésippe le frère de Joseph</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κλωπας - Κλωπᾶς</font>\n<br><br>origine : Araméen</td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2833":"<h1>knetho</h1>\n<p>Strong n° 2833 <i>Prononciation [knay'-tho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>gratter, chatouiller, donner la démangeaison</li>\n<li>démanger</li>\n<li>désireux d'entendre quelque chose d'agréable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κνήθω<br>      1</b> gratter, <i>d’où</i> irriter, ARSTT. <i>Probl. 31, 3 ;</i> ANTH. <i>12, 238 ;</i><br><b>      2</b> chatouiller, NT. <i>2Tim. 4, 3 ;</i> CLÉM. <i>328 ;</i><br><b><i>Moy.</i></b> gratter sur soi, <i>acc</i>. ARSTT. <i>H.A. 9, 1, 10</i>.<br><span><b>Étym</b>. κνάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κνηθω - κνήθω</font>\n<br><br>vient du mot primaire 'knao' (râcler)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2834":"<h1>Knidos</h1>\n<p>Strong n° 2834 <i>Prononciation [knee'-dos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Cnide (Angl. Cnidus ou Gnidus) = « voué à Vénus », « lieu des orties »\n<ol><li>ville sur un promontoire de la côte sud-ouest de l'Asie Mineure en face de l'île de Cos, distante d'environ 16 km. Le navire de Paul passa à côté en se rendant à Rome</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κνίδος, ου (ἡ)</b> <span>[ῐ]</span> Knidos (Cnide, <i>auj</i>. ruines près de Yazıköy) <i>v. de Carie,</i> HH. <i>Ap. 43 ;</i> HDT. <i>1, 144, etc. ;</i> ESCHL. <i>Pers. 891 ;</i> THC. <i>8, 36, etc. ;</i> XÉN. <i>Hell. 4, 3, 12, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κνιδος - Κνίδος</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2835":"<h1>kodrantes</h1>\n<p>Strong n° 2835 <i>Prononciation [kod-ran'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le quadrant, petite pièce de bronze équivalant au quart de l'as ; au temps de Christ, à peu près le quart d'un sou</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοδράντης, ου (ὁ)</b> le quadrans <i>ou</i> quart de l’as, NT. <i>Marc. 12, 42</i>.<br><span><b>Étym</b>. <i>lat</i>. quadrans, quadrantis.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοδραντης - κοδράντης</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2836":"<h1>koilia</h1>\n<p>Strong n° 2836 <i>Prononciation [koy-lee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout le ventre, l'intérieur en entier\n<ol type=\"a\">\n<li>distinction entre le supérieur (estomac) et l'inférieur</li>\n</ol>\n</li>\n<li>le ventre inférieur, les intestins, réceptacle des excréments</li>\n<li>le gosier\n<ol type=\"a\">\n<li>voué aux plaisirs du palais, à la gloutonnerie</li>\n</ol>\n</li>\n<li>la matrice, le lieu ou le fœtus est conçu et nourri jusqu'à la naissance\n<ol type=\"a\">\n<li>l'utérus des animaux</li>\n</ol>\n</li>\n<li>la partie interne de l'homme, l'âme, le cœur comme siège des pensées, sentiments, choix</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοιλία, ας (ἡ)</b> <i>propr</i>. cavité, creux, <i>particul. :</i><br><b>   I</b> cavité du ventre, <i>d’où :</i><br><b>      1</b> ventre, HDT. <i>2, 87 ;</i> AR. <i>Vesp. 794, Eq. 280, etc. ; particul</i>. partie du ventre des animaux où se développe le fœtus, ARR. <i>Epict. 2, 16, 43 ; 3, 22, 74 ;</i> ἡ κάτω κοιλία, l’estomac jusqu’au colon, le bas-ventre, PLAT. <i>Tim. 73</i> a ; AR. <i>Ran. 485 ;</i> ἡ ἄνω κοιλία, <i>ou abs</i>. ἡ κοιλία, l’estomac proprement dit, HPC. <i>476, 37, etc. ;</i> ARSTT. <i>P.A. 2, 3, 8, etc. ; particul</i>. estomac des ruminants, jabot des oiseaux, ARSTT. <i>H.A. 2, 17, 9 ; P.A. 3, 11, 8 ;</i><br><b>      2</b> les intestins, HDT. <i>2, 40, 86, etc. ; en parl. d’animaux,</i> AR. <i>Eq. 356 ; au pl</i>. AR. <i>Eq. 160, etc. ;</i> τὴν κοιλίαν λύειν, ARSTT. <i>Probl. 1, 40 et 43 ;</i> ATH. <i>32</i> e, dégager le ventre, rendre le ventre libre ;<br><b>      3</b> <i>p. suite,</i> selles, déjections du bas-ventre, HPC. <i>Aër. 287 ;</i> ATH. <i>33</i> b ; κ. ὑγρή, HPC. <i>1129</i> b, excréments liquides, diarrhée ; στερεή, σκληρή, HPC. <i>1129</i> b, excréments secs, durs, <i>etc. ;</i><br><b>   II</b> cavités dans diverses parties du corps, <i>particul. :</i><br><b>      1</b> boîte crânienne, RUF. <i>p. 36 ;</i><br><b>      2</b> cavité des poumons, HPC. <i>Art. 807 ;</i><br><b>      3</b> ventricule du cœur, ARSTT. <i>H.A. 1, 17, 1, etc. ;</i><br><b>      4</b> cavité où s’emboîte un os, HPC. <i>Art. 827 ;</i><br><b>      5</b> partie charnue d’un muscle, GAL. <i>5, 366 ;</i><br><b>      6</b> partie intérieure et charnue des doigts, ARÉT. <i>3, 8 ;</i><br><b>      7</b> <i>au plur</i>. parties creuses du corps d’un animal mort, <i>d’où</i> carcasse (d’animal) POL. <i>7, 15, 8 ;</i><br><b>   III</b> cavité, creux, <i>en gén</i>. (dans la terre, <i>etc</i>.) ARSTT. <i>Meteor. 1, 13, 23, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HPC. <i>70</i> c, <i>etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοιλια - κοιλία</font>\n<br><br>vient de koilos (« creux »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n23 fois dans 22 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (8)</li>\n<li>Jean (2)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2837":"<h1>koimao</h1>\n<p>Strong n° 2837 <i>Prononciation [koy-mah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui fait dormir, s'endormir</li>\n<li>métaph.\n<ol type=\"a\">\n<li>calmer, tranquilliser</li>\n<li>tomber de sommeil, s'endormir</li>\n<li>mourir</li>\n<li>οι κοιμωμενοι les morts <a class=\"ref\" data-r=\"1TH5.13\">1 Thessaloniciens 5.13</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοιμάω-ῶ</b> <span>(<i>f</i>. κοιμήσω, <i>ao</i>. ἐκοίμησα, <i>pf. inus. ; pass. f</i>. κοιμηθήσομαι, <i>ao</i>. ἐκοιμήθην, <i>pf</i>. κεκοίμημαι)</span><br><b>      1</b> étendre sur une couche, mettre au lit : τινα, OD. <i>3, 397,</i> qqn ; <i>en parl. d’une biche :</i> νεϐροὺς κοιμήσασα, OD. <i>4, 336,</i> ayant étendu ses faons sur une couche ;<br><b>      2</b> <i>p. suite,</i> faire reposer, faire dormir : τινα ὕπνῳ, OD. <i>12, 372,</i> plonger qqn dans le sommeil ; βλέφαρα ὕπνῳ, ESCHL. <i>Sept. 3 ;</i> ὄσσε, IL. <i>14, 236,</i> faire reposer ses yeux par le sommeil ;<br><b>      3</b> <i>par euphém. p</i>. faire mourir, SOPH. <i>El. 509 ;</i> φλόγα, ESCHL. <i>Ag. 597,</i> modérer une flamme ;<br><b>      4</b> <i>fig. càd</i>. assoupir, apaiser, calmer : ἀνέμους, IL. <i>12, 281 ;</i> κύματα, OD. <i>12, 169,</i> les vents, les flots ; ὀδύνας, IL. <i>16, 524 ;</i> ἕλκος, SOPH. <i>Ph. 650,</i> des douleurs, la souffrance que cause une blessure ; στόμα, ESCHL. <i>Ag. 1247,</i> clore sa bouche ; μένος, ESCHL. <i>Eum. 832,</i> calmer la colère, le désir ; <i>au pass</i>. PLAT. <i>Rsp. 571</i> ;<br><i>Pass.-moy. (f</i>. κοιμήσομαι, <i>ou avec forme pass</i>. κοιμηθήσομαι ; <i>ao</i>. ἐκοιμησάμην, <i>ou att. avec forme pass</i>. ἐκοιμήθην) :<br><b>      1</b> se coucher, coucher : τινι, HÉS. <i>Th. 213 ;</i> ξύν τινι, EUR. <i>Andr. 370,</i> avec qqn ; παρά τινι, HDT. <i>3, 68 ;</i> AR. <i>Eccl. 723,</i> auprès de qqn ;<br><b>      2</b> reposer, dormir, IL. <i>1, 476, 610 ;</i> HDT. <i>2, 95 ;</i> EUR. <i>Rhes. 439 ;</i> PLAT. <i>Conv. 203</i> d ; <i>en parl. d’animaux,</i> OD. <i>14, 411 ;</i> ὕπνον βαθύν, <i>ou simpl</i>. βαθὺν κοιμηθῆναι, LUC. <i>D. mar. 2, 3,</i> dormir d’un profond sommeil ;<br><b>      3</b> <i>en parl. du sommeil de la mort :</i> οἱ κοιμηθέντες, NT. <i>1Thess. 4, 13, etc., ou</i> κεκοιμημένοι, NT. <i>Matth. 27, 52, etc</i>. ceux qui dorment du sommeil éternel ;<br><b>      4</b> se poster <i>ou</i> camper pour une veille, veiller (<i>lat</i>. excubare) ESCHL. <i>Ag. 2 ;</i> XÉN. <i>Cyr. 1, 2, 4 et 9</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. dor</i>. κοιμάσω <span>[ᾱ]</span> ANTH. <i>7, 8 ; 12, 49. — Pass. ao. dor</i>. ἐκοιμάθην <span>[ᾱ]</span> SOPH. <i>El. 509. — Moy. prés. ion. 3 pl</i>. κοιμέονται, HDT. <i>2, 95</i>.<br><span><b>Étym</b>. κεῖμαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοιμαω - κοιμάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (6)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2838":"<h1>koimesis</h1>\n<p>Strong n° 2838 <i>Prononciation [koy'-may-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un repos, une prise de repos, le sommeil (mort) <a class=\"ref\" data-r=\"JHN11.13\">Jn 11.13</a></li>\n<li>une pause, un assoupissement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοίμησις, εως (ἡ) :<br>      1</b> action de se coucher, PLAT. <i>Conv. 183</i> a ; NT. <i>Joh. 11, 13 ;</i><br><b>      2</b> sommeil de la mort, SPT. <i>Sir. 18, 10</i>.<br><span><b>Étym</b>. κοιμάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοιμησις - κοίμησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2839":"<h1>koinos</h1>\n<p>Strong n° 2839 <i>Prononciation [koy-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>commun</li>\n<li>ordinaire, appartenant à la généralité\n<ol type=\"a\">\n<li>pour les Juifs : profane, Lévitiquement impur, souillé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοινός, ή, όν :<br>A</b> <i>en parl. de choses :</i><br><b>   I</b> commun à plusieurs personnes, ESCHL. <i>Pr. 795, etc. ;</i> SOPH. <i>O.C. 1500, etc. ;</i> κοινὰ τὰ τῶν φίλων, EUR. <i>Or. 725,</i> tout est commun entre amis ; <i>p. opp. à</i> ἴδιος, ATT. (EUR. <i>Andr. 376, etc.) ; avec un gén</i>. ATT. (ESCHL. <i>Pr. 1091, etc</i>.) ; PLUT. <i>M. 490</i> e, <i>etc. ; avec un dat</i>. ESCHL. <i>Ag. 523 ;</i> XÉN. <i>Œc. 21, 2 ;</i> PLAT. <i>Rsp. 369</i> e ; DÉM. <i>227, 5, etc</i>. commun à qqn <i>ou</i> à qqe ch. ; <i>avec une prép. :</i> ἐπὶ πᾶσι κ. PLAT. <i>Theæt. 185</i> c, commun à tous ; κ. κατ' ἀμφοτέρων, DYSC. <i>Synt. p. 147, 31,</i> commun aux uns et aux autres ; οὐ γίγνεταί μοί τι κ. πρός τινα, ANTH. <i>11, 141,</i> je n’ai rien de commun avec qqn ;<br><b>   II</b> <i>particul. en parl. de relations sociales et politiques,</i> commun à tout le peuple, public : τὸ κ. ἀγαθόν, THC. <i>5, 37,</i> le bien public ; τὰ κ. χρήματα, XÉN. <i>Hell. 6, 5, 34,</i> les ressources communes ; κοιναὶ ἀρχαί, POL. <i>22, 16, 11,</i> magistrats publics ; κοινὰ πράγματα, POL. <i>24, 5, 8,</i> affaires publiques ; κοινὰ ἐγκλήματα, POL. <i>20, 6, 1,</i> accusations d’un caractère public, concernant les affaires de l’État ; <i>subst. :</i><br><b>      1</b> τὸ κοινόν : l’État, ATT. (AR. <i>Eccl. 208, etc.) ; avec un gén</i>. τὸ κ. τῶν Σπαρτιητέων, HDT. <i>1, 67,</i> l’État des Spartiates ; <i>cf</i>. HDT. <i>6, 14 ;</i> POL. <i>8, 14, 7, etc. ; p. suite,</i> le gouvernement, les autorités publiques, THC. <i>1, 90, etc. ;</i> XÉN. <i>Cyr. 2, 2, 20, etc. ;</i> ἀπὸ τοῦ κοινοῦ, HDT. <i>5, 85, etc</i>. par l’autorité publique ; — le conseil de l’État, le sénat, <i>p. opp. à</i> ἡ πόλις, THC. <i>2, 12 ;</i> — consentement de tous, volonté <i>ou</i> décision commune : σὺν τῷ κοινῷ, HDT. <i>9, 87,</i> d’un consentement unanime ; ἄνευ τοῦ τῶν πάντων κοινοῦ, THC. <i>4, 78,</i> sans le consentement de la ligue ; — trésor public, HDT. <i>7, 44 ;</i> THC. <i>1, 80 ; 6, 6 ;</i> ἀπὸ κοινοῦ, XÉN. <i>An. 4, 7, 27,</i> avec les ressources communes ; — droit commun, droit de tous les citoyens, ARSTT. <i>Pol. 3, 13, 12 ;</i><br><b>      2</b> <i>plur</i>. τὰ κοινά, les affaires publiques : πρὸς τὰ κ. προσιέναι, ESCHN. <i>23, 37,</i> aborder la vie publique ; τὰ κ. διοικεῖν, DÉM. <i>15, 21, ou</i> πράττειν, PLUT. <i>M. 1127</i> d, administrer <i>ou</i> gérer les affaires publiques ; <i>p. suite,</i> l’État : τὰ κοινὰ τῶν Βοιωτῶν, POL. <i>20, 6, 1,</i> l’État des Béotiens ; — autorités publiques, HDT. <i>3, 156 ;</i> — ressources communes, <i>d’où</i> trésor public, AR. <i>Pl. 569 ;</i> DÉM. <i>95, 8, etc. ;</i><br><b>   III</b> communiqué, publié, EUR. <i>Hipp. 609 ;</i> commun, usuel, ARSTT. <i>Rhet. 1, 1, 12 ;</i> ἡ κοινὴ ἔννοια <i>ou</i> ἐπίνοια, POL. <i>2, 62, 2 ; 6, 5, 2,</i> le sens commun ; κοινὴ διάλεκτος, DH. <i>Isocr. 2,</i> dialecte commun, langue vulgaire ; οἱ κοινοί, EM. <i>405, 23 ; 692, 13,</i> les auteurs qui ont écrit en langue vulgaire ; κοινὰ ὀνόματα, DH. <i>Lys. 3,</i> noms communs ; κοινὸς τόπος, RHÉT. lieu commun ; <i>en mauv. part,</i> bas, vil, profane, impur, NT. <i>Marc. 7, 2 ; Rom. 14, 14, etc. ;</i><br><b>   IV</b> qui participe de deux caractères <i>ou</i> attributs : κοινὸς τῷ γένει, EM. <i>144, 32, etc</i>. de genre commun (masculin <i>ou</i> féminin) ; κοινὴ συλλαϐή, LGN <i>fr. 3, 11,</i> syllabe de quantité commune (longue <i>ou</i> brève) ;<br><b>B</b> <i>en parl. de pers. et de choses :</i><br><b>   I</b> qui participe à, qui est en communauté : ἔν τινι, SOPH. <i>O.R. 240, Aj. 267, etc</i>. de qqe ch. ;<br><b>   II</b> qui est d’une origine commune, de même race, de même nature, SOPH. <i>O.R. 261, O.C. 535, Ant. 1, 202 ;</i><br><b>   III</b> qui se prête à tous également, <i>càd. :</i><br><b>      1</b> sociable, affable, XÉN. <i>Cyn. 13, 9 ; avec le dat</i>. ISOCR. <i>4</i> d, <i>98</i> b ;<br><b>      2</b> équitable, impartial, THC. <i>3, 53 ; avec le dat</i>. LYS. <i>144, 21 ; en parl. d’événements :</i> τύχαι, THC. <i>5, 102,</i> chances égales ;<br><b>      3</b> accessible : τινι, PLAT. <i>Men. 91,</i> à qqn ; <i>en parl. d’un pays :</i> κ. τῶν τόπων ἁπάντων, ARSTT. <i>Pol. 7, 5, 4,</i> accessible de tous les points.<br><span>•<i> Cp</i>. -ότερος, THC. <i>5, 102 ;</i> ISOCR. <i>215</i> b, <i>etc. ;</i> ARSTT. <i>Rhet. 1, 1</i>. <i>• Sup</i>. -ότατος, AND. <i>19, 14 ;</i> PLAT. <i>Leg. 724</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ός, SOPH. <i>Tr. 207</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *kom, avec ; <i>cf. lat</i>. cum, com-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοινος - κοινός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (5)</li>\n<li>Romains (3)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2840":"<h1>koinoo</h1>\n<p>Strong n° 2840 <i>Prononciation [koy-no'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre commun\n<ol type=\"a\">\n<li>rendre impur (selon la loi Lévitique), profaner</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοινόω-ῶ</b> <span>(<i>f</i>. -ώσω, <i>ao</i>. ἐκοίνωσα, <i>pf. inus</i>.)</span> communiquer, <i>càd. :</i><br><b>      1</b> rendre commun à, communiquer à : τί τινι, ARSTT. <i>Pol. 2, 5, 15,</i> communiquer qqe ch. à qqn ; <i>d’où</i> mettre en commun : τι, THC. <i>1, 39,</i> qqe ch. ; τινί τι, PLAT. <i>Leg. 889</i> d, une ch. avec une autre ; <i>au pass</i>. être associé à, <i>dat</i>. EUR. <i>Andr. 38 ;</i><br><b>      2</b> communiquer, faire savoir : τί τινι, ESCHL. <i>Ch. 716 ;</i> EUR. <i>Med. 685 ;</i> AR. <i>Nub. 196 ;</i> THC. <i>2, 73 ;</i> τι ἔς τινα, EUR. <i>I.A. 44 ;</i> τινι περί τινος, ESCHL. <i>Suppl. 369,</i> qqe ch. à qqn ;<br><b>      3</b> mettre en communication, unir, <i>d’où au pass</i>. être uni, s’unir à, <i>dat</i>. PLAT. <i>Leg. 673</i> d ; <i>abs</i>. EUR. <i>Andr. 38, 217 ; fig</i>. être teint d’une couleur, <i>dat</i>. PLAT. <i>Tim. 59</i> b ;<br><b>      4</b> rendre commun à tous, <i>càd</i>. prostituer, profaner, souiller, NT. <i>Matth. 15, 11 ; Marc. 7, 23 ;</i> τί τινι, JOS. <i>Macc. 7,</i> souiller une chose d’une autre ;<br><b>      5</b> unir, <i>d’où</i> assembler, ajuster (les pièces d’une construction) HÉRON ;<br><b><i>Moy</i>. κοινόομαι-οῦμαι</b> <span>(<i>f</i>. κοινώσομαι, <i>ao</i>. ἐκοινωσάμην, <i>ao. pass</i>. ἐκοινώθην)</span><br><b>      1</b> communiquer, <i>càd</i>. mettre en commun : τι, ESCHL. <i>Ag. 1347 ;</i> PLAT. <i>Lach. 196</i> c, se communiquer qqe ch. l’un à l’autre ; τινι περί τινος, POL. <i>7, 16, 3,</i> se concerter sur qqe ch. avec qqn ; τί τινι, PD. <i>N. 3, 19,</i> associer une chose avec une autre ; <i>avec un acc. de chose et un dat. de pers</i>. τί τινι, HDN <i>7, 8, 2,</i> communiquer qqe ch. à qqn ;<br><b>      2</b> prendre une part de, entrer en communauté <i>ou</i> en participation de : τι, THC. <i>8, 8 ;</i> τινος, EUR. <i>Ph. 1709, Cycl. 634, Andr. 654,</i> de qqe ch. ; τινί τινος, EUR. <i>Andr. 933, ou</i> τι μετά τινος, THC. <i>8, 48,</i> de qqe ch. avec qqn ;<br><b>      3</b> entrer en communication avec, prendre conseil de : τῷ θεῷ, XÉN. <i>An. 5, 10, 15,</i> consulter la divinité.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. dor</i>. κοινάσομαι <span>[ᾱ]</span> PD. <i>N. 3, 19</i>.<br><span><b>Étym</b>. κοινός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοινοω - κοινόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (5)</li>\n<li>Actes (3)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2841":"<h1>koinoneo</h1>\n<p>Strong n° 2841 <i>Prononciation [koy-no-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>venir en communion ou camaraderie avec, devenir membre du partage, être un partenaire</li>\n<li>entrer en association, se joindre comme associé, devenir participant ou partenaire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοινωνέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐκοινώνησα, <i>pf</i>. κεκοινώνηκα)</span><br><b>   I <i>intr</i>.<br>      1</b> être en communauté avec, avoir en commun avec, prendre part à, <i>avec un gén. de chose :</i> τινος, ESCHL. <i>Ch. 166 ;</i> SOPH. <i>Tr. 546 ;</i> EUR. <i>Med. 302, I.T. 1067 ;</i> XÉN. <i>Mem. 2, 6, 22 ;</i> PLAT. <i>Crat. 434</i> b, <i>etc. ;</i> DÉM. <i>410, 10 ; 1335, 7,</i> avoir <i>ou</i> prendre une part de qqe ch. ; <i>avec le dat. de la pers</i>. τινι, EUR. <i>Her. 300 ;</i> PLAT. <i>Rsp. 343</i> d, <i>Leg. 844</i> c, s’associer à qqn ; <i>avec double rég. : le gén. de la chose et le dat. de la pers. :</i> τινός τινι, PLAT. <i>Leg. 686</i> a ; DÉM. <i>789, 2 ;</i> POL. <i>1, 6, 7, etc. ; avec le dat. de la pers. et une prép. :</i> τινι εἴς τι, PLAT. <i>Rsp. 453</i> a ; τινι περί τινος, POL. <i>31, 26, 6 ; avec le dat. de la pers. et l’acc. de la chose :</i> τί τινι, PLAT. <i>Rsp. 540</i> c, prendre part à qqe ch. avec qqn, être l’associé <i>ou</i> l’allié de qqn pour qqe ch. ; φόνον τινί, EUR. <i>El. 1048,</i> s’associer avec qqn pour un meurtre, accomplir un meurtre de complicité avec qqn ;<br><b>      2</b> avoir des relations intimes avec, <i>dat</i>. LUC. <i>D. deor. 1, 2 ; 10, 2 ;</i><br><b>      3</b> avoir un caractère commun <i>ou</i> du rapport avec : στολὴν ἥκιστα γυναικείᾳ κοινωνοῦσαν, XÉN. <i>Lac. 11, 3,</i> robe qui n’a rien de commun avec une robe de femme ; οὐδὲν κ. τῇ τραγῳδίᾳ, ARSTT. <i>Poet. 14, 4,</i> n’avoir rien de commun avec la tragédie ;<br><b>   II <i>tr</i>.<br>      1</b> mettre en communauté, associer : ἐγκώμια κεκοινωνημένα εὐχαῖς, PLAT. <i>Leg. 801</i> e, éloges associés à des vœux ;<br><b>      2</b> communiquer, faire part : τινί τινος, LUC. <i>Alex. 46, Philops. 34, etc</i>. de qqe ch. à qqn ;<br><b><i>Moy.</i></b> communiquer, faire part : τί τινι, ALCIPHR. <i>3, 72,</i> de qqe ch. à qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. impér. dor. 3 pl</i>. κοινανεόντων, THC. <i>5, 79</i>.<br><span><b>Étym</b>. κοινωνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοινωνεω - κοινωνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2842":"<h1>koinonia</h1>\n<p>Strong n° 2842 <i>Prononciation [koy-nohn-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>contribution volontaire (<a class=\"ref\" data-r=\"ROM15.26\">Romains 15.26</a>)</li>\n<li>assistance, libéralité (<a class=\"ref\" data-r=\"2CO8.4\">2 Corinthiens 8.4</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοινωνία, ας (ἡ) :<br>      1</b> action d’avoir en commun, de partager <i>ou</i> de participer à, communauté : τινός, EUR. <i>H.f. 1377,</i> de qqe ch. ;<br><b>      2</b> action d’être commun, d’avoir un rapport, une affinité : τίς κατόπτρου καὶ ξίφους κ. ; AR. <i>Th. 140,</i> quel rapport entre un miroir (de femme) et une épée ? ;<br><b>      3</b> échange de relations, communication, commerce, relations, société, PLAT. <i>Gorg. 507</i> e, <i>etc. ;</i> ARSTT. <i>Nic. 8, 9 ;</i> ἡ περὶ ἀνθρώπους πρὸς ἀλλήλους κ. PLAT. <i>Conv. 188</i> c, <i>ou</i> ἡ ἀνθρωπίνη κ. PLAT. <i>Pol. 276</i> b, les relations des hommes les uns avec les autres, la société humaine ; <i>au pl</i>. PLAT. <i>Leg. 861</i> e, <i>etc. ; particul</i>. relations intimes, EUR. <i>Bacch. 1277 ;</i> PLAT. <i>Leg. 721</i> a, <i>etc. ;</i> AMPHIS (ATH. <i>69</i> c) ;<br><b>      4</b> <i>p. suite,</i> sympathie, compassion, <i>d’où</i> aumône, NT. <i>Rom. 15, 26 ; Hebr. 13, 26</i>.<br><span><b>Étym</b>. κοινωνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοινωνια - κοινωνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 18 versets de 10 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (4)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Jean (4)</li>\n</ul>\n</td></tr>\n</table>","G2843":"<h1>koinonikos</h1>\n<p>Strong n° 2843 <i>Prononciation [koy-no-nee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>social, sociable, prêt à former et maintenir la communion et l'entente</li>\n<li>poussé à faire des autres des participants à ses biens, libéral, généreux</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοινωνικός, ή, όν :<br>      1</b> disposé à partager, à donner une part de, <i>gén</i>. LUC. <i>Tim. 56 ; abs</i>. ARSTT. <i>Rhet. 2, 24, 2 ;</i><br><b>      2</b> qui communique volontiers avec d’autres, communicatif, sociable, PLAT. <i>Def. 411</i> e ; ARSTT. <i>Pol. 3, 13 ;</i> POL. <i>2, 41, 1 ;</i> τὸ κ. ARR. <i>Epict. 3, 13, 5,</i> la sociabilité.<br><span><b>Étym</b>. κοινωνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοινωνικος - κοινωνικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2844":"<h1>koinonos</h1>\n<p>Strong n° 2844 <i>Prononciation [koy-no-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un partenaire, un associé, un camarade, un compagnon</li>\n<li>celui qui partage en toute chose\n<ol type=\"a\">\n<li>l'autel de Jérusalem sur lequel les sacrifices sont offerts\n<ol>\n<li>partage dans le culte des Juifs</li>\n</ol>\n</li>\n<li>participants des démons\n<ol>\n<li>entrer en association avec eux, parce qu'ils sont les auteurs du culte païen</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοινωνός, ός, όν :<br>      1</b> qui participe à, qui s’associe à, associé, compagnon : τινος, ESCHL. <i>Suppl. 343, etc. ;</i> EUR. <i>H.f. 584, etc. ;</i> PLAT. <i>Leg. 6, 755</i> c, <i>etc. ;</i> XÉN. <i>Cyr. 7, 5, 71, etc. ;</i> τινι, EUR. <i>El. 637 ;</i> περί τινος, PLAT. <i>Leg. 810</i> c, qui prend sa part de qqe ch. ; κ. τινί τινος, XÉN. <i>Mem. 2, 6, 24,</i> qui partage qqe ch. avec qqn ; <i>en mauv. part,</i> κ. τοῦ κακοῦ, SOPH. <i>Tr. 730,</i> associé à (<i>càd</i>. qui est cause d’) un malheur ; <i>abs</i>. compagnon, PLAT. <i>Rsp. 333</i> b, <i>etc. ;</i><br><b>      2</b> <i>adj</i>. κοινωνῷ ξίφει, EUR. <i>I.T. 1173,</i> avec une épée complice, par un meurtre commis de complicité.<br><span><b>Étym</b>. κοινός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοινωνος - κοινωνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2845":"<h1>koite</h1>\n<p>Strong n° 2845 <i>Prononciation [koy'-tay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lieu pour se reposer, pour dormir\n<ol type=\"a\">\n<li>un lit, une couche</li>\n</ol>\n</li>\n<li>le lit conjugal\n<ol type=\"a\">\n<li>le lit de l'adultère</li>\n</ol>\n</li>\n<li>cohabitation, concubinage, légal ou illicite\n<ol type=\"a\">\n<li>relations sexuelles</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοίτη, ης (ἡ) :<br>A</b> couche :<br><b>   I</b> <i>au propre,</i> OD. <i>19, 341 ;</i> SOPH. <i>El. 194, etc. ;</i> EUR. <i>Tr. 494, etc. ;</i> XÉN. <i>Mem. 2, 3, 16 ;</i> PLAT. <i>Leg. 942</i> d ; <i>particul</i>. lit nuptial, ESCHL. <i>Suppl. 806 ;</i> SOPH. <i>Tr. 922 ;</i> EUR. <i>Med. 151, etc. ; au plur. joint à</i> λέκτρων : κοῖται λέκτρων, EUR. <i>Alc. 925, Med. 436 ; au sg</i>. κοίτα (<i>dor</i>.) λεχέων, EUR. <i>Hipp. 154 ; d’où</i> relations intimes, NT. <i>Rom. 9, 10 ; en mauv. part,</i> libertinage, NT. <i>Rom. 13, 13 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> lit de la mer, ESCHL. <i>Ag. 566, ou</i> d’un fleuve, ANON. BYZ. <i>114, 38, 7 dout. ;</i><br><b>      2</b> gîte d’animal, <i>particul</i>. nid d’oiseau, EUR. <i>Ion 155 ;</i> toile d’araignée, ARSTT. <i>H.A. 9, 39, 4 ;</i><br><b>      3</b> corbeille, PLUT. <i>Phoc. 28, etc. ;</i><br><b>B</b> action de se coucher, <i>d’où</i> action d’aller dormir, HDT. <i>1, 18 ;</i> XÉN. <i>Cyr. 2, 3, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κοίτα, EUR. <i>Med. 151, 437</i>.<br><span><b>Étym</b>. κεῖμαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοιτη - κοίτη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2846":"<h1>koiton</h1>\n<p>Strong n° 2846 <i>Prononciation [koy-tone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une chambre à coucher\n<ol type=\"a\">\n<li>l'intendant de la chambre à coucher, le chambellan</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοιτών, ῶνος (ὁ) :<br>      1</b> chambre à coucher, AR. (<i>Com. fr. 2, 947</i>) ; MATR. (ATH. <i>135</i> d) ; LUC. <i>As. 2, etc. ;</i><br><b>      2</b> trésor du prince, fisc, DC. <i>61, 5</i>.<br><span><b>Étym</b>. κοίτη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοιτων - κοιτών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2847":"<h1>kokkinos</h1>\n<p>Strong n° 2847 <i>Prononciation [kok'-kee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vêtement ou habit écarlate</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόκκινος, η, ον</b> <span>[ῐ]</span> d’un rouge écarlate, PLUT. <i>Fab. 15 ;</i> NT. <i>Hebr. 9, 19 ;</i> τὰ κόκκινα, ARR. <i>Epict. 3, 22, 10, etc</i>. vêtements écarlates.<br><span><b>Étym</b>. κόκκος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοκκινος - κόκκινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G2848":"<h1>kokkos</h1>\n<p>Strong n° 2848 <i>Prononciation [kok'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un grain, une graine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόκκος, ου (ὁ) :<br>   I</b> graine <i>ou</i> pépin, <i>particul</i>. de la grenade, HH. <i>Cer. 373, 412 ;</i> HDT. <i>4, 143 ;</i> HPC. <i>605, 39, etc. ; fig</i>. νόου δέ μοι οὐκ ἔνι κ. TIMON (SEXT. <i>M. 11, 172</i>) je n’ai pas un grain de bon sens ;<br><b>   II</b> cochenille, <i>insecte,</i> TH. <i>H.P. 3, 7, 3 ;</i> kermès, <i>animal parasite du chêne-kermès (quercus coccifera</i> L.) <i>qui sert à teindre en écarlate,</i> DIOSC. <i>4, 48 ; p. suite,</i> teinture d’écarlate provenant du kermès, DROM. (ATH. <i>240</i> d) ;<br><b>   III</b> <i>p. anal. :</i><br><b>      1</b> pilule, A. TR. <i>5, p. 283 ;</i><br><b>      2</b> <i>au plur</i>. testicules, ANTH. <i>12, 222</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοκκος - κόκκος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2849":"<h1>kolazo</h1>\n<p>Strong n° 2849 <i>Prononciation [kol-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>élaguer, ébrancher, comme les arbres et le vent</li>\n<li>enlever la gourme, modérer, restreindre</li>\n<li>châtier, corriger, punir</li>\n<li>être puni</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολάζω</b> <span>(<i>f</i>. άσω <span>[ᾰ]</span>, <i>ao</i>. ἐκόλασα, <i>pf. inus. ; pass. f</i>. κολασθήσομαι, <i>ao</i>. ἐκολάσθην, <i>pf</i>. κεκόλασμαι)</span> <i>propr</i>. tronquer, mutiler, <i>d’où :</i><br><b>   I</b> diminuer :<br><b>      1</b> élaguer, émonder (des arbres) <i>acc</i>. TH. <i>H.P. 2, 7, 6, C.P. 1, 17, 9, etc. ;</i><br><b>      2</b> <i>p. suite,</i> retrancher tout ce qui dépasse, ramener à la juste mesure, <i>d’où fig</i>. contenir : τὰς ἐπιθυμίας, PLAT. <i>Gorg. 491</i> e, contenir les désirs ; τὸ πλεονάζον, PLUT. <i>M. 663</i> e, contenir ce qui est excessif ; δίαιτα κεκολασμένη, LUC. <i>Herm. 86,</i> régime de vie sévère ; τὸ εὐπειθὲς καὶ κεκολασμένον, ARSTT. <i>Nic. 3, 12, 8,</i> caractère docile et facile à contenir ;<br><b>      3</b> <i>p. suite,</i> châtier, punir : τινά, EUR. <i>Bacch. 1323 ;</i> AR. <i>Nub. 7 ;</i> XÉN. <i>Hell. 5, 3, 7, etc</i>. qqn ; τινὰ λόγοις, SOPH. <i>Aj. 1160</i> a dresser à qqn des paroles de blâme ; θανάτῳ, EUR. <i>Hel. 1188 ;</i> LYS. <i>179, 35 ;</i> πληγαῖς, PLAT. <i>Leg. 784</i> c ; ταῖς μεγίσταις τιμωρίαις, ISOCR. <i>13</i> a, punir qqn de mort, en le frappant, des plus grands châtiments ; <i>avec double acc</i>. τὰ σεμνὰ ἔπη κόλαζ' ἐκείνους, SOPH. <i>Aj. 1108,</i> châtiez-les en paroles sévères ;<br><b>   II</b> faire tort à ; <i>au pass</i>. être lésé, EL. <i>N.A. 3, 24 ;</i><br><b><i>Moy.</i></b> punir, AR. <i>Vesp. 406 ;</i> PLAT. <i>Prot. 324</i> c.<br><span><b><span class=\"arrow\"></span></b> ARSTT. <i>Rhet. 1, 10, 17 :</i> κολάζω <i>marque répression du tort de l’offenseur, τιμωρέομαι la réparation du tort fait à l’offensé. Fut. contr. 2 sg</i>. κολᾷ, AR. <i>Eq. 456</i>.<br><span><b>Étym</b>. κόλος ; <i>cf</i>. κολούω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολαζω - κολάζω</font>\n<br><br>vient de 'kolos' (nain)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2850":"<h1>kolakeia</h1>\n<p>Strong n° 2850 <i>Prononciation [kol-ak-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>flatterie, discours flatteur, paroles flatteuses, adulation</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολακεία, ας (ἡ)</b> <span>[ᾰκ]</span> flatterie, adulation, PLAT. <i>Gorg. 466</i> a ; ESCHN. <i>76, 42 ;</i> DÉM. <i>127 fin</i>.<br><span><b>Étym</b>. κόλαξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολακεια - κολακεία</font>\n<br><br>vient d'un dérivé de 'kolax'(un flatteur)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G2851":"<h1>kolasis</h1>\n<p>Strong n° 2851 <i>Prononciation [kol'-as-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>correction, punition, châtiment, pénalité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόλασις, εως (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> action d’élaguer, élagage, TH. <i>C.P. 3, 18, 2 ;</i><br><b>      2</b> correction, châtiment, punition, PLAT. <i>Prot. 326</i> d, <i>etc. ;</i> ARSTT. <i>Rhet. 1, 10, 4 ;</i> PLUT. <i>M. 562</i> f ; <i>au plur</i>. PLAT. <i>Prot. 323</i> e, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Sur la différence de</i> κόλασις et <i>de</i> τιμωρία, <i>v</i>. κολάζω.<br><span><b>Étym</b>. κολάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολασις - κόλασις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> diffère de  dans le sens qu'il est disciplinaire et fait référence à celui qui le subit, tandis que le second est pénal et fait référence à la satisfaction de celui qui l'inflige</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2852":"<h1>kolaphizo</h1>\n<p>Strong n° 2852 <i>Prononciation [kol-af-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>frapper avec le poing, donner une gifle à quelqu'un, boxer (comme un gladiateur), donner un coup, un soufflet</li>\n<li>maltraiter, traiter avec violence et insulte</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολαφίζω</b> <span>[ᾰ]</span> souffleter, <i>acc</i>. NT. <i>Matth. 26, 67 ; 1Cor. 4, 11</i>.<br><span><b>Étym</b>. κόλαφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολαφιζω - κολαφίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2853":"<h1>kollao</h1>\n<p>Strong n° 2853 <i>Prononciation [kol-lah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>coller, lier, cimenter, assembler ensemble</li>\n<li>joindre ou lier fermement ensemble</li>\n<li>se joindre à, adhérer à</li>\n<li>s'unir fortement à (se dit surtout de l'union sexuelle)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολλάω-ῶ</b> <span>(<i>ao</i>. ἐκόλλησα ; <i>pass. ao</i>. ἐκολλήθην, <i>pf</i>. κεκόλλημαι)</span><br><b>      1</b> coller, souder : τι πρός τι, PLAT. <i>Tim. 82</i> d, <i>ou</i> περί τι, PLAT. <i>Tim. 75</i> d, une chose à une autre ; <i>en parl. de métaux,</i> PLUT. <i>M. 619</i> a ; <i>t. de méd</i>. appliquer une ventouse, ARÉT. <i>p. 76</i> d ;<br><b>      2</b> <i>fig</i>. unir fortement : τινί τι, EMPÉD. <i>275 Mullach,</i> une chose à une autre ; <i>joint à</i> συνδέω, PLAT. <i>Leg. 776</i> a ; <i>en parl. de pers. :</i> τινά τινι, NT. <i>Luc. 15, 15 ; Ap. 9, 26, etc</i>. unir une personne à une autre ; κεκόλληται γένος πρὸς ἄτᾳ, ESCHL. <i>Ag. 1566,</i> cette race est indissolublement liée au malheur.<br><span><b>Étym</b>. κόλλα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολλαω - κολλάω</font>\n<br><br>vient de 'kolla' (« colle forte »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (5)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2854":"<h1>kollourion</h1>\n<p>Strong n° 2854 <i>Prononciation [kol-loo'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>préparation composée de produits divers et utilisée comme remède pour les paupières collées</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολλούριον, ου (τὸ)</b> emplâtre, collyre, HPC. <i>609, 44</i>.<br><span><b>Étym</b>. <i>cf</i>. κολλύριον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολλουριον - κολλούριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2855":"<h1>kollubistes</h1>\n<p>Strong n° 2855 <i>Prononciation [kol-loo-bis-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un changeur de monnaie, un banquier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολλυϐιστής, οῦ (ὁ)</b> changeur, banquier, LYS. (POLL. <i>7, 33</i>) ; NT. <i>Joh. 2, 15 ; Matth. 21, 12 ; Marc. 11, 15</i>.<br><span><b>Étym</b>. κόλλυϐος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολλυβιστης - κολλυβιστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2856":"<h1>koloboo</h1>\n<p>Strong n° 2856 <i>Prononciation [kol-ob-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mutiler, amputer</li>\n<li>dans le N.T : raccourcir, abréger, diminuer, raccourcir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολοϐόω-ῶ :<br>      1</b> mutiler, tronquer, ARSTT. <i>P.A. 3, 8 ;</i> POL. <i>1, 80, 13 ;</i><br><b>      2</b> <i>p. suite,</i> raccourcir, ARSTT. <i>H.A. 1, 1, 20, etc. ; en parl. du temps,</i> NT. <i>Marc. 13, 20 ; au pass</i>. NT. <i>Matth. 24, 22</i>.<br><span><b>Étym</b>. κολοϐός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολοβοω - κολοβόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G2857":"<h1>Kolossai</h1>\n<p>Strong n° 2857 <i>Prononciation [kol-os-sah'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Colosses (Angl. Colosse) = « monstruosités »\n<ol><li>ville de l'Asie Mineure au sud-ouest de la Phrygie, sur le Lycos, non loin à l'est de la jonction de cette rivière avec le Méandre, proche de Laodicée et Hiérapolis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κολοσσαί, ῶν (αἱ)</b> Kolosses (<i>auj</i>. Honaz) <i>v. de la Grande-Phrygie,</i> HDT. <i>7, 30 ;</i> XÉN. <i>An. 1, 2, 6</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κολοσσαι - Κολοσσαί</font>\n<br><br>apparemment féminin pluriel de kolossos (« colossal »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2858":"<h1>Kolossaeus</h1>\n<p>Strong n° 2858 <i>Prononciation [kol-os-sayoos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Colossien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κολοσσαευς - κολασσαεύς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>","G2859":"<h1>kolpos</h1>\n<p>Strong n° 2859 <i>Prononciation [kol'-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le devant du corps entre les bras</li>\n<li>le sein d'un vêtement, le creux formé par la partie supérieure d'un vêtement plutôt large, lié par une ceinture, utilisé pour garder et transporter des objets, (un pli, une poche)</li>\n<li>une baie dans la mer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόλπος, ου (ὁ) :<br>   I</b> sein :<br><b>      1</b> sein de mère <i>ou</i> de nourrice, IL. <i>6, 400, 467, 483, etc. ;</i><br><b>      2</b> ventre, entrailles, <i>d’ord. au plur</i>. EUR. <i>Hel. 1159 ;</i> CALL. <i>Jov. 15 ;</i> SEXT. <i>p. 348, 2 ; au sg</i>. CALL. <i>Del. 214 ;</i><br><b>   II</b> pli : pli d’un vêtement, IL. <i>22, 80 ;</i> OD. <i>15, 468 ;</i> ESCHL. <i>Sept. 1039 ;</i> HDT. <i>6, 125 ;</i> POL. <i>3, 33, 2, etc. ; au pl</i>. IL. <i>9, 570 ;</i> PD. <i>O. 6, 51 ;</i><br><b>   III</b> <i>p. anal. :</i><br><b>      1</b> repli <i>ou</i> enfoncement de la mer entre deux vagues, <i>ou p.-ê</i>. le sein de la mer, l’intérieur de la mer, IL. <i>18, 140 ; 21, 125 ; au pl</i>. OD. <i>5, 52 ;</i><br><b>      2</b> sein de la terre, OPP. <i>C. 3, 11 ;</i> PHALAR. <i>Ep. 12 ; d’où</i> l’intérieur des enfers, AR. <i>Av. 694 ;</i><br><b>      3</b> sinuosité d’un littoral, <i>d’où</i> golfe, IL. <i>2, 560 ;</i> PD. <i>P. 4, 87 ;</i> ESCHL. <i>Pr. 837, Pers. 86 ;</i> SOPH. <i>fr. 527, etc. ;</i><br><b>      4</b> cavité, vallée profonde, PD. <i>O. 9, 131 ; 14, 33 ;</i> SOPH. <i>Ant. 1121 ;</i> EUR. <i>Tr. 130 ;</i> AR. <i>Ran. 373 ;</i><br><b>      5</b> sorte de fistule, P. EG. <i>4, 48</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολπος - κόλπος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2860":"<h1>kolumbao</h1>\n<p>Strong n° 2860 <i>Prononciation [kol-oom-bah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plonger, nager</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολυμϐάω-ῶ</b>, nager, plonger, s’enfoncer, <i>avec</i> εἰς <i>et l’acc</i>. PLAT. <i>Lach. 193</i> c, <i>Prot. 350</i> a ; NT. <i>Ap. 27, 43</i>.<br><span><b>Étym</b>. κόλυμϐος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολυμβαω - κολυμβάω</font>\n<br><br>vient de kolumbos (un plongeur)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2861":"<h1>kolumbethra</h1>\n<p>Strong n° 2861 <i>Prononciation [kol-oom-bay'-thrah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lieu pour plonger, un réservoir ou bassin pour se baigner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολυμϐήθρα, ας (ἡ)</b> piscine, bain, PLAT. <i>Rsp. 453</i> d ; ALEX. (ATH. <i>18</i> c) ; DS. <i>11, 25, etc</i>.<br><span><b>Étym</b>. κολυμϐάω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολυμβηθρα - κολυμβήθρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (5)</li>\n</ul>\n</td></tr>\n</table>","G2862":"<h1>kolonia</h1>\n<p>Strong n° 2862 <i>Prononciation [kol-o-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une colonie\n<ol type=\"a\">\n<li>la cité de Philippes est ainsi appelée car Octavius y avait implanté une colonie Romaine</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κολωνία, ας (ἡ)</b> = <i>lat</i>. cŏlōnĭa, colonie, NT. <i>Ap. 6, 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κολωνια - κολωνία</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2863":"<h1>komao</h1>\n<p>Strong n° 2863 <i>Prononciation [kom-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>laisser les cheveux pousser, avoir une longue chevelure</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κομάω-ῶ :<br>      1</b> être chevelu, avoir une chevelure longue, IL. <i>2, 542, etc. ;</i> HDT. <i>1, 82 ; 2, 36 ;</i> XÉN. <i>Lac. 11, 3 ;</i> PLAT. <i>Gorg. 524</i> c ; ARSTT. <i>Rhet. 1, 8, 3, etc. ;</i><br><b>      2</b> avoir une longue crinière, IL. <i>8, 42 ; 13, 24 ;</i><br><b>      3</b> <i>en parl. de comètes,</i> ARAT. <i>1092 ;</i><br><b>      4</b> <i>fig. en parl. de feuilles, de fleurs,</i> HH. <i>Cer. 454 ;</i> A. RH. <i>1, 928 ;</i> CALL. <i>Dian. 41 ;</i> DP. <i>950 ;</i><br><b>      5</b> <i>en parl. de la chevelure elle-même,</i> être longue <i>ou</i> forte, OPP. <i>C. 3, 27 ;</i> PHILSTR. <i>Ep. 25 ;</i><br><b>      6</b> prendre soin de sa chevelure <i>ou</i> porter sa chevelure longue, <i>en signe de force, de joie, etc. ; d’où</i> être fier, s’enorgueillir, AR. <i>Nub. 545, Pl. 170 ; joint à</i> ὑψαυχεῖν καὶ μεγαληγορεῖν, CHRYSIPP. (PLUT. <i>M. 1038</i> d) ; ἐπί τινι, HDT. <i>5, 71 ;</i> AR. <i>Vesp. 1317 ;</i> LUC. <i>Nigr. 1 ;</i> ANTH. <i>11, 322 ;</i> τινι, OPP. <i>C. 3, 192,</i> de qqe ch. ; διά τινα, AR. <i>Pl. 170,</i> à cause de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κομέω, HDT. A. RH., <i>etc. ll. cc. Épq</i>. κομόω, <i>d’où prés. ind. 3 pl</i>. κομόωσιν, DP. <i>950 ;</i> OPP. <i>C. 3, 27 ; part. fém</i>. κομόωσα, A. RH. <i>3, 928 ; plur. masc</i>. κομόωντες, IL. <i>2, 542 ; duel</i> κομόωντε, IL. <i>13, 24</i>.<br><span><b>Étym</b>. κόμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κομαω - κομάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G2864":"<h1>kome</h1>\n<p>Strong n° 2864 <i>Prononciation [kom'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cheveux, chevelure</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόμη, ης (ἡ) :<br>   I</b> chevelure, IL. <i>22, 406 ;</i> SOPH. <i>O.C. 1261, etc. ;</i> EUR. <i>Hel. 1240, etc. ; au plur</i>. IL. <i>17, 51 ;</i> OD. <i>6, 231 ;</i> PD. <i>P. 4, 145 ;</i> EUR. <i>Bacch. 694 ;</i> PLAT. <i>Phæd. 89</i> b ; κόμαι πρόσθετοι, XÉN. <i>Cyr. 1, 3, 2,</i> cheveux ajoutés <i>ou</i> postiches, perruque ;<br><b>   II</b> barbe, ARR. <i>Epict. 4, 8, 4 ;</i><br><b>   III</b> <i>p. anal. :</i><br><b>      1</b> chevelure de comète, ARSTT. <i>Meteor. 1, 6, 8 ;</i><br><b>      2</b> barbe de bouc, <i>plante,</i> TH. <i>H.P. 7, 7, 1 ;</i><br><b>      3</b> feuillage des arbres, OD. <i>23, 195 ;</i><br><b>      4</b> touffe <i>ou</i> tête feuillue d’une plante, DIOSC. <i>4, 165 ;</i><br><b>      5</b> tentacules (?) de la seiche, ARSTT. <i>H.A. 5, 18, 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. κόμα <span>[ᾱ]</span> PD. <i>l. c. etc</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κομη - κόμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2865":"<h1>komizo</h1>\n<p>Strong n° 2865 <i>Prononciation [kom-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aimer, prendre soin de, pourvoir à</li>\n<li>prendre et transporter pour prendre soin et préserver</li>\n<li>apporter, emmener</li>\n<li>porter, transporter pour soi, rapporter\n<ol type=\"a\">\n<li>recevoir, obtenir : la bénédiction promise</li>\n<li>recevoir ce qui était précédemment sien, retrouver, recouvrer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κομίζω</b> <span>(<i>f</i>. κομιῶ, <i>ao</i>. ἐκόμισα, <i>pf</i>. κεκόμικα)</span><br><b>   I</b> prendre soin de, <i>d’où :</i><br><b>      1</b> soigner avec sollicitude, <i>en parl. de vieillards, d’enfants, etc. :</i> τινά, IL. <i>24, 541 ;</i> OD. <i>15, 546, etc</i>. qqn ; <i>particul</i>. nourrir, élever, OD. <i>20, 68 ;</i><br><b>      2</b> introduire (dans la ville) THC. <i>3, 65 ;</i><br><b>      3</b> <i>en parl. de choses,</i> donner des soins à, s’occuper activement de : τι, IL. <i>6, 490 ;</i> OD. <i>21, 350 ; 23, 355,</i> de qqe ch. ; δῶμα, OD. <i>16, 74,</i> s’occuper des soins de la maison ; <i>en ce sens, rare chez les Att</i>. ESCHL. <i>Ch. 262, 344 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> emporter pour mettre en lieu sûr, à l’abri : νεκρόν, IL. <i>13, 196,</i> emporter un mort (pour le soustraire à l’ennemi) ; χλαῖναν, IL. <i>2, 183,</i> ramasser un manteau (pour qu’il ne soit pas perdu), <i>d’où abs</i>. sauver : τινὰ ἐκ θανάτου, PD. <i>P. 3, 97,</i> sauver qqn de la mort ; <i>fig</i>. ἀοιδοὶ καὶ λόγοι τὰ καλὰ ἔργ' ἐκόμισαν, PD. <i>N. 6, 52,</i> les aèdes et la renommée ont tiré de l’oubli les belles actions ;<br><b>      2</b> emporter (pour déposer en terre <i>ou</i> porter au bûcher) SOPH. <i>Aj. 1397 ;</i><br><b>   III</b> <i>p. ext. :</i><br><b>      1</b> emporter sur soi : χροῒ ἄκοντα, IL. <i>14, 456,</i> un javelot enfoncé dans la peau ;<br><b>      2</b> emporter <i>ou</i> emmener avec soi comme butin : χρυσόν, IL. <i>2, 875 ;</i> ἵππους, IL. <i>11, 738,</i> de l’or, des chevaux ; <i>d’où</i> κ. ἔπαινον, SOPH. <i>O.C. 1411,</i> obtenir de la gloire ;<br><b>      3</b> emmener, transporter (par terre <i>ou</i> par mer) HDT. <i>5, 43, etc. ;</i><br><b>      4</b> apporter, amener, introduire : τινά, SOPH. <i>Aj. 530,</i> amener qqn ; ξενικὸν νόμισμα, PLAT. <i>Leg. 742</i> c, une monnaie étrangère ; τὴν φιλοσοφίαν εἰς τοὺς Ἕλληνας, ISOCR. <i>227</i> a, introduire la philosophie chez les Grecs ; θράσος τινὶ κ. ESCHL. <i>Ag. 530,</i> donner du courage à qqn ;<br><b>   IV</b> ramener (des enfers, de l’exil, <i>etc.) avec</i> πάλιν, PLAT. <i>Phæd. 107</i> e ; <i>d’où au pass</i>. revenir, HDT. <i>5, 98 ;</i> LYS. <i>102, 1 ;</i> ἐπ' οἴκου, THC. <i>2, 33, ou</i> οἴκαδε, PLAT. <i>Rsp. 614</i> b, chez soi ;<br><b><i>Moy.</i></b> :<br><b>A <i>tr</i>.<br>   I</b> prendre soin de, <i>d’où :</i><br><b>      1</b> accueillir, donner l’hospitalité à : τινα ᾧ ἐνὶ οἴκῳ, IL. <i>8, 284, ou</i> τινα ἐς τὴν οἰκίαν, AND. <i>16, 37 ;</i> IS. <i>36, 25,</i> à qqn dans sa maison ;<br><b>      2</b> donner ses soins à, <i>acc</i>. HÉS. <i>O. 391, 598 ;</i><br><b>   II.1</b> emporter pour mettre à l’abri : τινα, IL. <i>1, 594,</i> qqn ;<br><b>      2</b> emporter pour déposer en terre, IS. <i>71, 13 ;</i><br><b>   III.1</b> emporter sur soi : ἔγχος ἐν χροΐ, IL. <i>22, 286,</i> recevoir une javeline dans le corps ;<br><b>      2</b> emporter avec soi, <i>d’où</i> remporter, gagner, obtenir : καρπὸν ἀπό τινος, XÉN. <i>Cyr. 1, 5, 10,</i> recueillir le fruit de qqe ch. ; δόξαν, EUR. <i>Hipp. 432,</i> obtenir de la gloire ; ἆθλα, PLAT. <i>Rsp. 621</i> d, des prix ; χάριν, THC. <i>3, 58 ;</i> DÉM. <i>264 fin,</i> recueillir de la reconnaissance ; τὰς χάριτας, ARSTT. <i>Nic. 9, 7,</i> se concilier les bonnes grâces de qqn ; τί τινος, SOPH. <i>O.R. 580 ;</i> τι παρά τινος, THC. <i>1, 43 ;</i> τι ἀπό τινος, XÉN. <i>Cyr. 1, 5, 10,</i> obtenir qqe ch. de qqn ; τινα οἰκεῖον, ISOCR. <i>133</i> e, faire de qqn son familier, se concilier l’amitié de qqn ;<br><b>      3</b> transporter : τὸ ἄγαλμα ἐπὶ Δήλιον, HDT. <i>6, 118,</i> la statue à Dèlion ; ποίμνας ἐς δόμους, SOPH. <i>Aj. 63,</i> emmener les troupeaux dans sa demeure ;<br><b>      4</b> recouvrer : τὴν βασιλείαν, AR. <i>Av. 549,</i> la royauté ; τοὺς νεκρούς, THC. <i>1, 113,</i> ramasser ses morts (pendant une trêve) ; recevoir de l’argent dû, recouvrer une dette, AR. <i>Vesp. 690 ;</i> PLAT. <i>Rsp. 507</i> a ; AND. <i>6, 11 ;</i> DÉM. <i>1291 fin ;</i> τὴν θυγατέρα, IS. <i>69, 30,</i> reprendre sa fille (après la mort de son mari) ;<br><b>B <i>intr.</i></b> se transporter : ἐς Βαϐυλῶνα, HDT. <i>1, 185,</i> à Babylone ; παρά τινα, HDT. <i>1, 73,</i> auprès de qqn ; ἔξω οἴκων, EUR. <i>Tr. 167,</i> hors de la maison ; <i>abs</i>. ESCHL. <i>Pr. 392</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. épq</i>. κομιζέμεν, OD. <i>23, 355 ; ao. épq</i>. ἐκόμισσα, IL. <i>2, 875 ; dor</i>. ἐκόμιξα, PD. <i>N. 2, 19 ; P. 4, 159. Moy. fut. ion</i>. κομιεῦμαι, HDT. <i>8, 62 ; 2 sg</i>. κομιέαι, HDT. <i>7, 49 ; ao. épq</i>. ἐκομισσάμην, OD. <i>14, 316, ou</i> κομισσάμην, IL. <i>8, 284</i>.<br><span><b>Étym</b>. κομέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κομιζω - κομίζω</font>\n<br><br>vient du mot primaire 'komeo' (soigner, prendre soin de)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>Hébreux (3)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G2866":"<h1>kompsoteron</h1>\n<p>Strong n° 2866 <i>Prononciation [komp-sot'-er-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>en meilleur état, mieux, meilleur, plus convenable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κομψοτερον - κομψότερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2867":"<h1>koniao</h1>\n<p>Strong n° 2867 <i>Prononciation [kon-ee-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couvrir de chaux, plâtrer, blanchir par lavage\n<ol type=\"a\">\n<li>les Juifs avaient coutume de blanchir l'entrée de leurs tombeaux en avertissement du risque de souillure si on les touchait</li>\n<li>terme appliqué à l'hypocrite qui cache sa malice sous un air extérieur de piété</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κονιάω-ῶ :<br>      1</b> enduire de chaux, de plâtre, DÉM. <i>36, 16 ; 689, 24 ;</i> PLUT. <i>M. 673</i> d ; SPT. <i>Deut. 27, 2, 4 ;</i> NT. <i>Matth. 23, 27, etc. ; ou p. anal</i>. de poix, DS. <i>19, 94 ;</i><br><b>      2</b> <i>fig</i>. plâtrer, farder, PHILSTR. <i>Ep. 22 ;</i><br><b><i>Moy.</i></b> enduire de chaux <i>ou</i> de plâtre, ARSTT. <i>H.A. 8, 2, 34</i>.<br><span><b>Étym</b>. κονία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κονιαω - κονιάω</font>\n<br><br>vient de 'konia' (poussière, par analogie, chaux)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2868":"<h1>koniortos</h1>\n<p>Strong n° 2868 <i>Prononciation [kon-ee-or-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>poussière qui s'élève, poussière qui vole</li>\n<li>épousseter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κονιορτός, οῦ (ὁ)</b> <span>[ῐ]</span><br><b>      1</b> poussière qui s’élève de terre, HDT. <i>8, 65 ;</i> THC. <i>4, 34 ;</i> PLAT. <i>Rsp. 496</i> d ; PLUT. <i>Fab. 16, M. 97</i> b ; <i>p. anal</i>. cendre qui vole, THC. <i>4, 34 ;</i><br><b>      2</b> <i>fig</i>. être vil et méprisable, DÉM. <i>547 ;</i> ANAXANDR. (ATH. <i>242</i> f) ; ARISTOPHON (ATH. <i>238</i> d).<br><span><b>Étym</b>. κόνις, ὄρνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κονιορτος - κονιορτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2869":"<h1>kopazo</h1>\n<p>Strong n° 2869 <i>Prononciation [kop-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>devenir las ou fatigué</li>\n<li>cesser une violence, chose furieuse qui cesse</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοπάζω</b>, être fatigué, <i>d’où</i> se relâcher, se reposer, se calmer, cesser, <i>en parl. du vent,</i> HDT. <i>7, 191, etc. ; de la tempête,</i> NT. <i>Matth. 14, 32 ; Marc. 4, 39 ; 6, 51 ; de la chaleur,</i> LGS <i>1, 8 ; de la maladie,</i> HPC. <i>1027</i> d, <i>etc. ; avec le gén</i>. κ. τοῦ θυμοῦ, SPT. <i>Esth. 2, 1,</i> laisser tomber sa colère.<br><span><b>Étym</b>. κόπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπαζω - κοπάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G2870":"<h1>kopetos</h1>\n<p>Strong n° 2870 <i>Prononciation [kop-et-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lamentation en se frappant la poitrine en signe de douleur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοπετός, οῦ (ὁ)</b> coup dont on se frappe la poitrine en signe de douleur, PLUT. <i>Fab. 17 ;</i> ANTH. <i>11, 122 ;</i> NT. <i>Ap. 8, 2</i>.<br><span><b>Étym</b>. κόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπετος - κοπετός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2871":"<h1>kope</h1>\n<p>Strong n° 2871 <i>Prononciation [kop-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action de couper, une coupure</li>\n<li>être mis en morceaux, massacrer, abattre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοπή, ῆς (ἡ) :<br>      1</b> incision, SOPH. <i>fr. 380 ;</i><br><b>      2</b> choc, ARSTT. <i>Mund. 4, 7 ;</i><br><b>      3</b> action de piler dans un mortier, A. APHR. <i>Probl. 1, 67 ;</i><br><b>      4</b> meurtre, carnage, NT. <i>Hebr. 7, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπη - κοπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2872":"<h1>kopiao</h1>\n<p>Strong n° 2872 <i>Prononciation [kop-ee-ah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être las, fatigué, épuisé (par un dur travail ou des fardeaux, ou du chagrin)</li>\n<li>travailler avec un effort important, travailler dur\n<ol type=\"a\">\n<li>un travail physique</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοπιάω-ῶ :<br>      1</b> être las, fatigué, AR. <i>Th. 795 ;</i> ARSTT. <i>H.A. 8, 26 ; Probl. 5, 7 ;</i> τὰ σκέλη, ALEX. (DL. <i>3, 27</i>) des jambes ; <i>p. suite,</i> être las, dégoûté, blasé : ὑπό τινος, AR. <i>Av. 734,</i> être dégoûté de qqe ch. ; <i>avec un part. :</i> κοπιῶ ζῶν, ANTH. <i>12, 46,</i> je suis las de vivre ; <i>cf</i>. EPIC. (CLÉM. <i>594</i>) ; PLUT. <i>M. 185</i> e ;<br><b>      2</b> travailler, prendre de la peine : εἴς τι, NT. <i>1Tim. 4, 10, etc. ;</i> ἔν τινι, NT. <i>1Tim. 5, 17 ;</i> τι, NT. <i>Joh. 4, 38,</i> pour qqe ch. ; <i>abs</i>. NT. <i>Luc. 5, 5 ; 12, 27 ; Matth. 6, 28, etc. ;</i><br><b><i>Moy.</i></b> se lasser, se fatiguer, ARSTT. <i>Probl. 5, 7</i>.<br><span><b>Étym</b>. κόπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπιαω - κοπιάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 21 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Actes (1)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>2 Timothée (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G2873":"<h1>kopos</h1>\n<p>Strong n° 2873 <i>Prononciation [kop'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>battre</li>\n<li>se frapper la poitrine de chagrin, de douleur</li>\n<li>travail\n<ol type=\"a\">\n<li>inquiéter\n<ol>\n<li>faire de la peine, importuner</li>\n</ol>\n</li>\n<li>travail intense uni à de la peine</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόπος, ου (ὁ) :<br>      1</b> coup, ESCHL. <i>fr. 131 ; particul</i>. coup dont on se frappe la poitrine, <i>en signe de deuil,</i> EUR. <i>Tr. 789 au plur. ;</i><br><b>      2</b> peine, souffrance, ESCHL. <i>Suppl. 210 ;</i> SOPH. <i>Ph. 880 ;</i> AR. <i>Pl. 321 ;</i><br><b>      3</b> <i>p. suite,</i> fatigue, lassitude, XÉN. <i>Eq. 4, 2 ;</i> EUR. <i>Ph. 859, etc. ;</i> AR. <i>Lys. 541 ; au plur</i>. EUR. <i>Rhes. 124 ;</i> PLAT. <i>Rsp. 537</i> b ; PLUT. <i>M. 127</i> b.<br><span><b>Étym</b>. κόπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπος - κόπος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – donne la prééminence à l'effort (travail demandant de la force)\n<br><br> – se réfère à la fatigue\n<br><br> – se réfère à la peine et à la privation (principalement en exposé poétique)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 19 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2874":"<h1>kopria</h1>\n<p>Strong n° 2874 <i>Prononciation [kop-ree'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fumier, engrais</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοπρία, ας (ἡ) :<br>      1</b> tas de fumier, SIM. AM. <i>fr. 7, 6 ;</i> ARSTT. <i>Mir. 141 ;</i> STR. <i>316 ;</i> SPT. <i>Job 2, 8, etc. ;</i><br><b>      2</b> fumier, PHIL. <i>2, 525</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. ion</i>. κοπρίῃσιν, SIM. <i>l. c</i>.<br><span><b>Étym</b>. κόπρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπρια - κοπρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G2875":"<h1>kopto</h1>\n<p>Strong n° 2875 <i>Prononciation [kop'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couper, frapper,</li>\n<li>découper, arracher</li>\n<li>se frapper la poitrine de chagrin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόπτω</b> <span>(<i>f</i>. κόψω, <i>ao</i>. ἔκοψα, <i>pf. inus. ; pass. ao.2</i> ἐκόπην, <i>pf</i>. κέκομμαι)</span><br><b>   I. 1</b> frapper à coups répétés, <i>d’où</i> frapper, <i>en gén. :</i> τὴν θύραν, AR. <i>Pl. 1097 ;</i> XÉN. <i>Hell. 5, 4, 7 ;</i> PLUT. <i>Alc. 8,</i> frapper à la porte ; <i>abs</i>. τί κόπτεις ; AR. <i>Eccl. 976,</i> pourquoi frappes-tu à la porte ? <i>avec double acc. :</i> κ. τινὰ παρήϊον, IL. <i>23, 690,</i> frapper qqn à la joue ; <i>particul</i>. frapper avec une arme (arc, IL. <i>10, 513 ;</i> javeline, OD. <i>8, 528) ; fig</i>. κ. ῥήμασι, ANTH. <i>11, 335,</i> blesser par des paroles maladroites ;<br><b>      2</b> abattre en frappant : τινὰ ποτὶ γαίῃ, OD. <i>9, 290,</i> frapper qqn contre terre ; βοῦς, XÉN. <i>An. 2, 1, 5,</i> abattre des bœufs ;<br><b>      3</b> secouer, fatiguer par des secousses répétées : ἀναϐάτην, XÉN. <i>Eq. 1, 4,</i> un cavalier, <i>en parl. du cheval ; fig</i>. ἐρωτήμασι, PLUT. <i>Phoc. 7,</i> importuner <i>ou</i> harceler de questions ;<br><b>   II</b> couper, <i>càd. :</i><br><b>      1</b> séparer en coupant : κεφαλὴν ἀπὸ δειρῆς, IL. <i>13, 203,</i> séparer la tête du cou ; χεῖράς τ' ἠδὲ πόδας, OD. <i>22, 477,</i> couper les mains et les pieds ; δένδρα, THC. <i>2, 75 ;</i> XÉN. <i>Hell. 5, 2, 43,</i> couper des arbres, les abattre, <i>d’où :</i> χώραν, XÉN. <i>Hell. 3, 2, 26, etc</i>. dévaster un pays en coupant les arbres ;<br><b>      2</b> couper en menus morceaux : κύπερον, HDT. <i>4, 71,</i> du souchet ;<br><b>      3</b> entamer, <i>particul</i>. entailler : τὰ μέτωπα μαχαίρῃσι, HDT. <i>2, 61,</i> taillader le visage à coups d’épées ; <i>en parl. de navires endommagés par l’ennemi,</i> THC. <i>4, 14 ; 8, 13 ;</i> PLUT. <i>Alc. 27 ; en parl. d’animaux (oiseaux, serpents, poissons, vers, etc</i>.) becqueter, mordre, ronger, <i>etc</i>. IL. <i>12, 204, etc. ;</i> ARSTT. <i>H.A. 9, 37 ;</i> σῖτος κόπτεται, TH. <i>H.P. 8, 11, 2,</i> le blé est mangé des insectes ; <i>fig</i>. endommager, avarier : φρενῶν κεκομμένος, ESCHL. <i>Ag. 479,</i> qui a l’esprit frappé, la raison atteinte ;<br><b>      4</b> frapper avec le marteau, forger : δεσμούς, IL. <i>18, 379 ;</i> OD. <i>8, 274,</i> des liens ; νόμισμα, HDT. <i>3, 56 ;</i> ARSTT. <i>Œc. 2, 20 ;</i> AR. <i>Ran. 721,</i> frapper une monnaie ;<br><b>      5</b> <i>fig</i>. rebattre, fatiguer, user par la fatigue : τινά, DÉM. <i>1439, 17 ;</i> HÉGÉSIPPE (ATH. <i>290</i> b) ; PLUT. <i>Phoc. 7,</i> qqn ; τὴν ἀκρόασιν, DH. <i>Comp. 19,</i> rebattre les oreilles ; <i>au pass</i>. être rebattu, fatigué : τινι, DÉM. <i>22, 22,</i> de qqe ch. ;<br><b><i>Moy.</i></b> :<br><b>   I <i>tr.</i></b> frapper (une monnaie) HDT. <i>4, 166 ;</i> EL. <i>V.H. 10, 12 ;</i><br><b>   II <i>intr</i>.<br>      1</b> se frapper : κεφαλήν, IL. <i>22, 33 ;</i> HDT. <i>2, 161,</i> se frapper la tête (de chagrin, de désespoir, <i>etc</i>.) ;<br><b>      2</b> <i>abs</i>. se frapper la poitrine <i>en signe de deuil,</i> ESCHL. <i>Pers. 683 ;</i> PLAT. <i>Phæd. 60</i> a, <i>etc., et avec un acc</i>. κόπτεσθαί τινα, AR. <i>Lys. 396, etc. ;</i> ANTH. <i>11, 135, litt</i>. se frapper la poitrine au sujet de qqn, pleurer qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Act. part. pf.2 épq. au sens d’un prés</i>. κεκοπώς, IL. <i>13, 60 ;</i> OD. <i>18, 335. Fut. moy. au sens act</i>. SPT. <i>Jer. 22, 18, etc. ; au sens pass</i>. SIB. <i>3, 651 et 731</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *kop-, frapper, battre, couper, <i>ou emprunt à un substrat pré-grec ou pré-indo-europ., cf</i>. σκάπτω, σκέπαρνον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοπτω - κόπτω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2876":"<h1>korax</h1>\n<p>Strong n° 2876 <i>Prononciation [kor'-ax]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un corbeau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόραξ, ακος (ὁ)</b> <span>[ᾰκ]</span><br><b>   I</b> corbeau, PD. <i>O. 2, 157 ;</i> ESCHL. <i>Suppl. 751 ; comme oiseau de proie, joint à</i> λύκος, LUC. <i>Tim. 8 ;</i> ἐς (<i>jamais εἰς chez les Att</i>.) κόρακας ἀπάγειν ; ἔρρειν, AR. <i>Pax 500 ;</i> ALEX. (ATH. <i>610</i> e) <i>etc. ; ou</i> βάλλειν, AR. <i>Nub. 133 ;</i> LUC. <i>Philopatr. 26 ; ou abs</i>. ἐς κόρακας, AR. <i>Vesp. 982 ; postér</i>. εἰς κόρακας, PLUT. <i>M. 860</i> e, s’en aller, se jeter <i>ou</i> être jeté aux corbeaux, <i>formule d’imprécation, l’abandon d’un corps livré en pâture aux corbeaux étant pour les Grecs le suprême déshonneur ;</i> οὐκ ἐς κόρακας ἀποφθερεῖ ; AR. <i>Nub. 789,</i> n’iras-tu pas te faire périr aux corbeaux ? ἐς κόρακας οἰχήσεται, AR. <i>Vesp. 51,</i> il ira aux corbeaux ; ἐξελαύνειν τινὰ ἐς κόρακας ἐκ τῆς οἰκίας, AR. <i>Nub. 123,</i> chasser qqn de la maison et l’envoyer aux corbeaux ; <span><i>prov</i>. πάντα τάδ' ἐν κοράκεσσι καὶ ἐν φθόρῳ</span>, THGN. <i>833,</i> tout cela est abandonné aux corbeaux et à la ruine ; λευκὸν ἰδεῖν κόρακα, ANTH. <i>11, 417,</i> voir un corbeau blanc ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> corbeau, <i>constellation,</i> ARAT. <i>448 ;</i><br><b>      2</b> poisson, DIPH. (ATH. <i>356</i> a) ; <i>cf</i>. κοράκινος ;<br><b>      3</b> cormoran, <i>oiseau aquatique,</i> ARSTT. <i>H.A. 8, 3, 15 ;</i><br><b>      4</b> <i>n. de divers objets recourbés comme le bec du corbeau, particul</i>. marteau de porte, ANTH. <i>11, 203 ;</i> instrument de torture, LUC. <i>Nec. 11 ;</i> machine de guerre, DS. <i>17, 44 ;</i> croc, POL. <i>1, 22 ;</i> MOSCHION HIST. (ATH. <i>208</i> d) ; corbeau, bec, cliquet, rochet, pièce d’arrêt (dans les machines de jet) HÉRON, BITON ; harpon, ATHÉNÉE MÉC. ; corbeau, pont-levis (s’abattant sur un navire ennemi) PHIL. BYZ.<br><span><b>Étym</b>. <i>indo-europ</i>. *kor-, corbeau ; <i>cf</i>. κορώνη, <i>lat</i>. corvus, cornīx.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοραξ - κόραξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2877":"<h1>korasion</h1>\n<p>Strong n° 2877 <i>Prononciation [kor-as'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une fille, une demoiselle, une jeune fille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοράσιον, ου (τὸ)</b> <span>[ᾱ]</span> petite fille, fillette, <i>t. familier,</i> PLAT. (DL. <i>3, 33</i>).<br><span><b>Étym</b>. κόρη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κορασιον - κοράσιον</font>\n<br><br>vient d'un dérivé présumé de 'kore' (jeune fille, vierge)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (5)</li>\n</ul>\n</td></tr>\n</table>","G2878":"<h1>korban</h1>\n<p>Strong n° 2878 <i>Prononciation [kor-ban']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>corban = « offrande »\n<ol>\n<li>un don offert à Dieu</li>\n<li>trésor sacré</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κορβαν</font> &lt; קרבן - <font face=\"Georgia\">κορβᾶν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2879":"<h1>Kore</h1>\n<p>Strong n° 2879 <i>Prononciation [kor-eh']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Coré (Angl. Korah) = « calvitie »\n<ol><li>un des hommes qui se sont rebellés contre Moïse</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κορε</font> &lt; קרח - <font face=\"Georgia\">Κόρε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G2880":"<h1>korennumi</h1>\n<p>Strong n° 2880 <i>Prononciation [kor-en'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>rassasier, donner à satiété, satisfaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κορέννυμι</b> <span>(<i>f</i>. έσω, <i>ao</i>. ἐκόρεσα ; <i>pass. ao</i>. ἐκορέσθην, <i>pf</i>. κεκόρεσμαι ; <i>part. pf. act. ion</i>. κεκορηώς <i>au sens pass</i>.)</span><br><b>   I</b> rassasier : τινά τινι, IL. <i>13, 831, ou</i> τινος, SOPH. <i>Ph. 1156,</i> qqn de qqe ch. ; κέαρ, ESCHL. <i>Pr. 165,</i> rassasier <i>ou</i> réjouir son cœur ; θυμὸν μολπῇ, A. RH. <i>3, 897,</i> rassasier <i>ou</i> réjouir son cœur d’un chant ;<br><b>   II</b> <i>pass. (ao</i>. ἐκορέσθην) <i>et moy. (ao</i>. ἐκορεσάμην) :<br><b>      1</b> se rassasier, être rassasié (de vin, de nourriture, de viande, <i>etc.) gén</i>. IL. <i>11, 562 ; 19, 167 ;</i> OD. <i>14, 28 ;</i> EUR. <i>Hipp. 112, etc. ; dat</i>. THGN. <i>1269 ; fig</i>. ὕϐρι κεκορημένος, HDT. <i>3, 80,</i> rassasié d’outrages ; <i>avec un part</i>. κλαίουσα κορέσσατο, OD. <i>20, 59,</i> elle se rassasia de pleurs ;<br><b>      2</b> avoir le dégoût de, être fatigué de, <i>gén. :</i> ἀέθλων, OD. <i>23, 350 ;</i> πολέμου, AR. <i>Pax 1283,</i> de luttes, de guerre ; <i>avec un part</i>. IL. <i>18, 287,</i> être fatigué de, <i>etc. ; part</i>. κεκορηώς, OD. <i>18, 372 ;</i> NONN. <i>D. 5, 34,</i> rassasié, <i>d’où</i> dégoûté, fatigué de, <i>gén</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. poét</i>. κορέσσω, ANTH. <i>14, 135 ; épq</i>. κορέω, IL. <i>13, 831 ; 17, 241 ; ao. poét</i>. ἐκόρεσσα, ANTH. <i>7, 204, etc. Pf.2 part. épq. au sens pass</i>. κεκορηώς, OD. NONN. <i>D. ll. cc. Pass. ao. pass. 3 pl. poét</i>. ἐκόρεσθεν, AR. <i>Pax 1283. Pf. ion</i>. κεκόρημαι, IL. <i>18, 287 ;</i> OD. <i>8, 98, etc. Fut. ant</i>. κεκορήσομαι, MAX. <i>π. κατ. 117. — Moy. ao. épq. 3 sg</i>. ἐκορέσσατο, <i>ou</i> κορέσσατο, OD. <i>20, 59 ; 1 pl</i>. κορεσσάμεθα, IL. <i>22, 427 ; part</i>. κορεσσάμενος, IL. <i>19, 167</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ḱerh₃-, croître ; <i>cf</i>. κόρος¹.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κορεννυμι - κορέννυμι</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2881":"<h1>Korinthios</h1>\n<p>Strong n° 2881 <i>Prononciation [kor-in'-thee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un Corinthien, et habitant de Corinthe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κορίνθιος, α, ον</b>, de Corinthe, Corinthien, HDT. <i>5, 87 ;</i> SOPH. <i>O.R. 774 ;</i> ἡ Κορινθία (<i>s.-e</i>. γῆ) XÉN. <i>Hell. 4, 4, 5, etc</i>. le territoire de Corinthe ; οἱ Κορίνθιοι, les Corinthiens, HDT. <i>1, 14, etc. ;</i> THC. <i>1, 13, etc. ;</i> XÉN. <i>Hell. 4, 4, 17, etc. ; avec jeu de mots sur</i> κόρεις, AR. <i>Nub. 710</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κορινθιος - Κορίνθιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2882":"<h1>Korinthos</h1>\n<p>Strong n° 2882 <i>Prononciation [kor'-in-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Corinthe (Angl. Corinth) = « rassasié »\n<ol><li>une ancienne et fameuse cité de Grèce, sur l'Isthme de Corinthe, à environ 65 km à l'ouest d'Athènes, capitale de la province sénatoriale d'Achaïe</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κόρινθος, ου</b> (ἡ, <i>qqf</i>. ὁ) Corinthe, <i>v. et territoire d’Achaïe,</i> IL. <i>2, 570 ;</i> HDT. <i>3, 52 ;</i> SOPH. <i>O.R. 1394, etc</i>.<br><span><b><span class=\"arrow\"></span></b> ὁ Κ. ORACL. (HDT. <i>5, 92</i>) ; DH. <i>4, 29 ;</i> STR. <i>378, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κορινθος - Κόρινθος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G2883":"<h1>Kornelios</h1>\n<p>Strong n° 2883 <i>Prononciation [kor-nay'-lee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Corneille (Angl. Cornelius) = « d'une corne »\n<ol><li>un centenier Romain de la cohorte Italienne basée à Césarée qui se convertit au Christianisme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Κορνήλιος, ου (ὁ)</b> = <i>lat</i>. Cornēlius, <i>n. d’h. rom</i>. PLUT. <i>Cæs. 47, 60, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κορνηλιος - Κορνήλιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (9)</li>\n</ul>\n</td></tr>\n</table>","G2884":"<h1>koros</h1>\n<p>Strong n° 2884 <i>Prononciation [kor'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un 'corus' ou cor, ou Kor, la plus grande mesure pour des produits secs (blé, farine etc.) d'environ 11 boisseaux (350 à 400 litres)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>κόρος, ου (ὁ) :<br>      1</b> satiété, <i>d’où</i> dégoût (de la nourriture, <i>etc</i>.) IL. <i>13, 636, etc. ; fig</i>. IL. <i>19, 221 ;</i> OD. <i>4, 103, etc. ;</i> κόρον ἔχειν τινός, EUR. <i>Alc. 185, etc</i>. être rassasié de qqe ch. ; κόρον ἔχειν, PLAT. <i>Phædr. 240</i> c, produire la satiété ; ἄχρι κόρου, DÉM. <i>400, 2 ;</i> ἐς κόρον, LUC. <i>H. conscr. 11, etc</i>. jusqu’à satiété ;<br><b>      2</b> dédain, orgueil, insolence, PD. <i>O. 2, 173, etc. ;</i> THGN. <i>153 ;</i> πρὸς κόρον, ESCHL. <i>Ag. 382,</i> avec insolence ; le Dédain personnifié, ORACL. (HDT. <i>8, 77</i>).<br><br>\n➁ <b>κόρος, ου (ὁ) :<br>   I</b> jeune garçon, <i>d’où :</i><br><b>      1</b> enfant dans le sein de la mère, IL. <i>6, 59 ;</i><br><b>      2</b> <i>en gén</i>. jeune garçon de condition libre, IL. <i>4, 321 ; 24, 347 ;</i> OD. <i>8, 264 ;</i> ESCHL. <i>fr. 37 ;</i> jeune garçon qui sert dans les sacrifices, IL. <i>1, 470 ; ou</i> dans un repas, OD. <i>1, 148 ;</i><br><b>      3</b> jeune guerrier, IL. <i>9, 86 ; 12, 196, etc. ;</i><br><b>      4</b> <i>à Lacédémone,</i> οἱ κόροι, les chevaliers (ἱππεῖς) ARCHYT. (STOB. <i>Fl. 43, 64</i>) ;<br><b>   II</b> jeune garçon, <i>par rapport au père et à la mère,</i> fils, OD. <i>19, 523 ;</i> SOPH. <i>Ph. 562 ;</i> EUR. <i>H.f. 1164 ;</i> EUB. (ATH. <i>47</i> c) ;<br><b>   III</b> <i>p. anal</i>. jeune pousse, rejeton, GAL. <i>Lex. Hipp. 19, 113 ; d’où</i> tige (de jonc, d’osier, <i>etc</i>.) LYSIPP. (<i>Com. fr. 1, 216</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et poét</i>. κοῦρος, IL. <i>1, 470 ; 4, 321, etc. ;</i> OD. <i>1, 148, etc. ;</i> TRAG. (<i>dans les chœurs) ; dor</i>. κῶρος, THCR. <i>Idyl. 15, 125 ; rare en prose,</i> PLAT. <i>Leg. 772</i> a.<br><span><b>Étym</b>. κόρη.</span></span><br><br>\n➂ <b>κόρος, ου (ὁ)</b> ordure, immondice (<i>propr</i>. ce qu’on balaye) <i>dans la loc</i>. βάλλ' ἐς κόρον, MÉN. (ATH. <i>446</i> d) va-t’en aux ordures, à la voirie.<br><span><b>Étym</b>. κορέω¹.</span><br><br>\n➃ <b>κόρος ⁴, ου (ὁ)</b> mesure de 6 médimnes attiques, JOS. <i>A.J. 15, 9, 2</i>.<br><span><b>Étym</b>. <i>mot hébreu</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κορος</font> &lt; כר - <font face=\"Georgia\">κόρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2885":"<h1>kosmeo</h1>\n<p>Strong n° 2885 <i>Prononciation [kos-meh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre en ordre, arranger, rendre prêt, préparer</li>\n<li>orner, ornementer</li>\n<li>métaph. embellir en honorant, gagner de l'honneur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοσμέω-ῶ :<br>   I</b> mettre en ordre, <i>d’où :</i><br><b>      1</b> arranger, mettre en bon ordre, disposer, <i>particul. en parl. d’une armée,</i> IL. <i>2, 554 ; 3, 1, etc. ;</i> EUR. <i>Rhes. 662 ; au pass</i>. XÉN. <i>Cyr. 2, 1, 26 ; d’où en gén</i>. disposer, arranger, préparer : δόρπον, OD. <i>7, 13, ou</i> δεῖπνον, PD. <i>N. 1, 32,</i> préparer un repas ; τράπεζαν, XÉN. <i>Cyr. 8, 2, 6,</i> dresser une table ; ἀοιδήν, HH. <i>6, 59,</i> arranger un chant ; λέϐητα, SOPH. <i>El. 1401,</i> orner l’urne funéraire ; <i>en parl. de pers</i>. ταπεινὸς καὶ κεκοσμημένος, PLAT. <i>Leg. 716</i> a, modeste et rangé, de mœurs régulières ;<br><b>      2</b> maintenir en ordre, <i>càd</i>. en repos, <i>acc</i>. EUR. <i>Rhes. 138 ;</i><br><b>      3</b> répartir, distribuer, HDT. <i>3, 91 ; 6, 41 ;</i><br><b>      4</b> <i>p. ext</i>. diriger, gouverner, commander (une ville, <i>etc.) acc</i>. HDT. <i>1, 59 ; 1, 100 ;</i> DH. <i>2, 7 ; en parl. de l’intelligence qui gouverne le monde,</i> PLAT. <i>Phæd. 97 ;</i> τὰ κοσμούμενα, SOPH. <i>Ant. 677,</i> les dispositions prises par ceux qui gouvernent ; <i>en Crète,</i> être κόσμος ARSTT. <i>Pol. 2, 10, 10 ;</i> POL. <i>23, 15, 1 ;</i><br><b>   II</b> <i>p. suite,</i> parer, orner :<br><b>      1</b> <i>au propre,</i> HÉS. <i>O. 72, etc. ; au pass</i>. être paré, HH. <i>Ven. 65 ;</i> κεκοσμημένος ἐσθῆτι ποικίλῃ καὶ χρυσοῖσι στεφάνοις, PLAT. <i>Ion 535,</i> paré d’une robe brodée et de couronnes d’or ; <i>en parl. d’armures,</i> BATR. <i>121 ;</i> HDT. <i>4, 180 ; de meubles, d’objets d’art,</i> PD. <i>I. 1, 27, etc. ; fig</i>. λόγον εὐρυθμίαις, ISOCR. <i>87</i> e, arranger un discours avec des phrases bien cadencées ; <i>cf</i>. EUR. <i>Med. 576 ;</i><br><b>      2</b> vanter, célébrer, <i>acc</i>. PD. <i>N. 6, 78 ;</i> PLAT. <i>Lys. 196</i> b, <i>Lach. 197</i> c ; DÉM. <i>321, 14 ;</i> ἐπὶ τὸ μεῖζον κ. THC. <i>1, 21,</i> embellir en exagérant ;<br><b>      3</b> honorer : νέκυν, EUR. <i>Tr. 1147,</i> un mort ; τάφον, SOPH. <i>Ant. 396,</i> donner des soins à une tombe ; κ. καὶ τιμᾶν, XÉN. <i>Cyr. 1, 3, 3,</i> parer (de vêtements, de bijoux) qui sont des marques d’honneur ;<br><b><i>Moy.</i></b> :<br><b>      1</b> arranger <i>ou</i> disposer pour soi : κοσμησάμενος πολιήτας, IL. <i>2, 806,</i> ayant disposé en bon ordre ses compatriotes ;<br><b>      2</b> parer pour soi <i>ou</i> sur soi : κ. τὰς κόμας, HDT. <i>7, 209,</i> se parer la chevelure ; χαλκοῖς σῶμ' ὅπλοις, EUR. <i>Ph. 1359,</i> se revêtir d’une belle armure d’airain.<br><span><b>Étym</b>. κόσμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοσμεω - κοσμέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (2)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G2886":"<h1>kosmikos</h1>\n<p>Strong n° 2886 <i>Prononciation [kos-mee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>du monde, ou appartenant au monde\n<ol type=\"a\">\n<li>relatif à l'univers</li>\n<li>terrestre</li>\n<li>mondain, ayant le caractère de cette période présente corrompue</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοσμικός, ή, όν :<br>      1</b> qui concerne l’univers, ARSTT. <i>Phys. 2, 4 ;</i> PLUT. <i>M. 119</i> f ; LUC. <i>Par. 11 ;</i><br><b>      2</b> du monde, mondain, <i>ou</i> séculier, <i>par opp. au clergé,</i> ECCL. ; NT. <i>Hebr. 9, 1</i>.<br><span><b>Étym</b>. κόσμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοσμικος - κοσμικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G2887":"<h1>kosmios</h1>\n<p>Strong n° 2887 <i>Prononciation [kos'-mee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>bien arrangé, bienséant, modeste, honorable, digne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόσμιος, α</b> <i>ou</i> <b>ος, ον :<br>   I</b> qui est en bon ordre, bien ordonné, bien réglé, <i>d’où :</i><br><b>      1</b> <i>au mor. en parl. de pers</i>. prudent, sage, décent, convenable, de mœurs bien réglées, honnête, <i>joint à</i> δίκαιοι καὶ σοφοί, AR. <i>Pl. 89 ; à</i> σώφρων, LYS. <i>163, 22 ; à</i> φρόνιμος, PLAT. <i>Phæd. 108</i> a ; κ. ἐν διαίτῃ, PLAT. <i>Rsp. 408</i> a, qui suit un régime de vie bien ordonné ;<br><b>      2</b> qui s’acquitte régulièrement de ses devoirs : πρὸς τοὺς θεούς, PLAT. <i>Conv. 193</i> a, envers les dieux ; <i>particul. en parl. de citoyens,</i> régulier, ATT. ;<br><b>      3</b> décent, modeste, XÉN. <i>Mem. 3, 11, 14 ;</i> τὸ κόσμιον, SOPH. <i>El. 872 ;</i> PLAT. <i>Leg. 802</i> e, décence, modestie ;<br><b>      4</b> paisible, calme, <i>en parl. d’un malade,</i> HPC. <i>Acut. 395 ;</i><br><b>   II</b> qui erre <i>ou</i> vit à travers le monde, citoyen du monde entier, <i>cf</i>. κοσμοπολίτης, PLUT. <i>M. 600</i> f.<br><span>•<i> Cp</i>. -ώτερος, ISOCR. <i>398</i> c ; <i>sup</i>. -ώτατος, PLAT. <i>Rsp. 564</i> e.<br><span><b>Étym</b>. κόσμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοσμιος - κόσμιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G2888":"<h1>kosmokrator</h1>\n<p>Strong n° 2888 <i>Prononciation [kos-mok-fat'-ore]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>seigneur du monde, prince de cet âge, les puissants de ce monde\n<ol type=\"a\">\n<li>le diable et ses démons</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κοσμο·κράτωρ, ορος (ὁ)</b> <span>[ᾰ]</span> maître du monde, ORPH. <i>H. 8, 11, 11, 11 ;</i> NT. <i>Eph. 6, 12</i>.<br><span><b>Étym</b>. κόσμος, κρατέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοσμοκρατωρ - κοσμοκράτωρ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G2889":"<h1>kosmos</h1>\n<p>Strong n° 2889 <i>Prononciation [kos'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un arrangement habile et harmonieux d'une constitution, d'un ordre, d'un gouvernement</li>\n<li>ornement, décoration, parure : l'arrangement des étoiles, les 'hôtes célestes', comme ornement des cieux (<a class=\"ref\" data-r=\"1PE3.3\">1 Pierre 3.3</a>)</li>\n<li>le monde, l'univers</li>\n<li>le cercle de la terre, la terre</li>\n<li>les habitants de la terre, les hommes, la race humaine</li>\n<li>la multitude sans Dieu, la masse des hommes séparés de Dieu, ceux qui sont hostiles à Christ</li>\n<li>les affaires du monde, la masse des choses terrestres\n<ol type=\"a\">\n<li>la totalité des biens terrestres, les richesses, avantages, plaisirs, etc, qui bien que creux, fragiles et fugitifs, poussent au désir, éloignent de Dieu, et sont des obstacles à la cause de Christ</li>\n</ol>\n</li>\n<li>tout ensemble de groupes ou de particuliers de toute sorte\n<ol type=\"a\">\n<li>les Gentils en contraste avec les Juifs (<a class=\"ref\" data-r=\"ROM11.12\">Romains 11.12</a>) etc.</li>\n<li>seulement les croyants (<a class=\"ref\" data-r=\"JHN1.29;3.16;3.17;6.33;12.47\">Jean 1.29 ; 3.16 ; 3.17 ; 6.33 ; 12.47</a> ; <a class=\"ref\" data-r=\"1CO4.9\">1 Corinthiens 4.9</a> ; <a class=\"ref\" data-r=\"2CO5.19\">2 Corinthiens 5.19</a>)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόσμος, ου (ὁ) :<br>   I</b> ordre, <i>d’où :</i><br><b>      1</b> bon ordre : κόσμῳ ἔρχεσθαι, IL. <i>12, 225,</i> aller en ordre ; κόσμῳ καθίζειν, OD. <i>13, 77,</i> s’asseoir en ordre ; κόσμῳ τιθέναι τὰ πάντα, HDT. <i>2, 52,</i> mettre tout en ordre ; σὺν κόσμῳ, HDT. <i>8, 86 ;</i> ἐν κόσμῳ, PLAT. <i>Conv. 223</i> b, en bon ordre ; φεύγειν, ἀπιέναι οὐδενὶ κόσμῳ, HDT. <i>3, 13 ; 8, 60,</i> fuir, s’éloigner sans aucun ordre, <i>etc. ;</i> οὐδένα κόσμον, HDT. <i>9, 65, 69 ;</i> κατ' οὐδένα κόσμον, PLUT. <i>Nic. 3,</i> sans aucun ordre ;<br><b>      2</b> <i>au mor</i>. bon ordre, convenance, bienséance : οὐ κατὰ κόσμον, IL. <i>2, 214 ;</i> OD. <i>8, 179,</i> non comme il convient, d’une façon inconvenante ; εὖ κατὰ κόσμον, IL. <i>10, 472,</i> bien comme il convient ; ἀμφὶ κόσμον, ESCHL. <i>Suppl. 246,</i> comme il convient, <i>càd</i>. avec prudence, sagesse <i>ou</i> honnêteté ;<br><b>      3</b> bon ordre, discipline, DÉM. <i>300, 19 ; p. opp. à</i> ἀκοσμία, SOPH. <i>fr. 726 ;</i><br><b>      4</b> organisation, construction : ἵππου, OD. <i>8, 492,</i> du cheval (de bois) ; <i>fig. en parl. d’institutions, de coutumes :</i> κόσμον τόνδε καταστησάμενος, HDT. <i>1, 99,</i> ayant établi ce cérémonial ; <i>d’où en gén</i>. ordre établi dans un État, THC. <i>8, 72 ;</i> μεταστῆσαι τὸν κ. THC. <i>4, 76,</i> changer l’ordre établi ; ἐκ τοῦ παρόντος κόσμου τὴν πόλιν μεταστήσας, THC. <i>8, 48,</i> ayant changé l’ordre établi et modifié la constitution de l’État ;<br><b>   II</b> <i>en parl. de pers</i>. le régulateur, le directeur, le magistrat suprême, <i>en Crète,</i> ARSTT. <i>Pol. 2, 10, 6 ;</i><br><b>   III</b> ordre de l’univers, <i>d’où :</i><br><b>      1</b> <i>chez les Pythagoriciens,</i> monde, univers, PYTHAG. (PLUT. <i>M. 886</i> b) ; <i>p. suite, chez les poètes philosophes, Empédocle, Parménide, etc. et en gén. chez les philosophes,</i> PLAT. <i>Tim. 27</i> a, <i>etc. ;</i> ARSTT. <i>Cæl. 1, 10, 10 ;</i><br><b>      2</b> <i>chez les stoïciens,</i> l’âme du monde, POSIDON. (DL. <i>7, 139</i>) ;<br><b>      3</b> <i>en parl. de parties diverses du monde :</i> le ciel, ISOCR. <i>78 ;</i> ARSTT. <i>Meteor. 1, 2, 2 ; au plur</i>. les mondes, <i>càd</i>. les astres (<i>p. opp. à</i> τὸ πᾶν, l’univers) PLUT. <i>M. 879</i> b ; l’organisme humain, l’homme : βραχὺς κ. PHIL. <i>2, 155, ou</i> μικρὸς κ. ANON. <i>V. Pyth. Theophil Kießling, Iamblichi De vita pythagorica, præter anonymus apud Photium De vita Pythagoræ etc., vol. 1, p. 114,</i> l’homme, un petit monde, un monde en raccourci ; le monde connu, la terre habitée, NT. <i>Matth. 16, 26 ;</i> le monde, la réunion des hommes, NT. <i>Joh. 7, 4, etc. ;</i> les choses terrestres, <i>p. opp</i>. aux choses du ciel, NT. <i>Joh. 12, 25, etc. ;</i><br><b>   IV</b> parure, ornement, <i>en parl. de la parure des femmes (lat</i>. mundus muliebris) IL. <i>14, 187 ;</i> XÉN. <i>Cyr. 8, 4, 24 ;</i> PLAT. <i>Rsp. 373</i> c, <i>etc. ; fig. en parl. de pers. chères ou remarquables,</i> HDT. <i>3, 123, etc. ;</i> XÉN. <i>Cyr. 6, 4, 3 ; en parl. d’un cheval,</i> IL. <i>4, 145 ; en parl. de choses en gén., d’un chant,</i> PD. <i>O. 3, 24, etc. ; des ornements du langage ou du style, particul. des épithètes,</i> ARSTT. <i>Rhet. 3, 7, 2 ; Poet. 21, 2, etc. ; p. suite,</i> gloire, honneur : κόσμον φέρει τινί, HDT. <i>8, 60, 142,</i> cela donne de la considération à qqn ; γυναιξὶ κόσμον ἡ σιγὴ φέρει, SOPH. <i>Aj. 293,</i> le silence donne aux femmes de la considération ; ἐν κόσμῳ καὶ τιμῇ εἶναί τινι, DÉM. <i>1400, 13,</i> être pour qqn un motif de considération et d’honneur ; <i>cf</i>. THC. <i>1, 5</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ḱeNs-, ordre ; <i>cf. lat</i>. cēnseō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοσμος - κόσμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n187 fois dans 152 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (9)</li>\n<li>Marc (3)</li>\n<li>Luc (3)</li>\n<li>Jean (79)</li>\n<li>Actes (1)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (21)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (4)</li>\n<li>1 Timothée (3)</li>\n<li>Hébreux (5)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (5)</li>\n<li>1 Jean (23)</li>\n<li>2 Jean (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G2890":"<h1>Kouartos</h1>\n<p>Strong n° 2890 <i>Prononciation [koo'-ar-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Quartus = « quatrième »\n<ol><li>chrétien de Corinthe, qui joignit ses salutations à celles de Paul aux Romains.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Κουαρτος - Κούαρτος</font>\n<br><br>origine : Latin (quatrième)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G2891":"<h1>koumi</h1>\n<p>Strong n° 2891 <i>Prononciation [koo'-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se lever, s'élever traduction littérale « Lève-toi », « debout »</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κουμι</font> &lt; קומי - <font face=\"Georgia\">κουμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G2892":"<h1>koustodia</h1>\n<p>Strong n° 2892 <i>Prononciation [koos-to-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>garde : utilisé pour les soldats romains gardant le sépulcre du Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κουστωδια - κουστωδία</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (3)</li>\n</ul>\n</td></tr>\n</table>","G2893":"<h1>kouphizo</h1>\n<p>Strong n° 2893 <i>Prononciation [koo-fid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être léger</li>\n<li>alléger\n<ol type=\"a\">\n<li>un navire en jetant la cargaison par dessus bord</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κουφίζω</b>, <i>f. att</i>. ιῶ :<br><b>A <i>intr</i>.<br>      1</b> être léger, HÉS. <i>O. 461 ;</i> EUR. <i>Hel. 1571 ;</i> DC. <i>40, 1 ; 50, 33 ;</i><br><b>      2</b> être allégé, éprouver du soulagement, SOPH. <i>Ph. 735 ;</i><br><b>B <i>tr</i>.<br>   I</b> rendre léger, donner de la légèreté à, alléger, <i>acc</i>. ARSTT. <i>Cæl. 4, 2, 8 ; avec le gén. de la ch. dont on allège qqn ou qqe ch.,</i> EUR. <i>Hel. 40 ; au pass</i>. κουφισθεὶς τοῦ βάρους, TH. <i>H.P. 4, 16, 2,</i> allégé de son fardeau ; <i>abs</i>. alléger un navire de sa cargaison, THC. <i>6, 34 ; au pass</i>. POL. <i>20, 5, 11 ; fig. :</i><br><b>      1</b> <i>en parl. de charges publiques, d’impôts, de dettes,</i> XÉN. <i>Mem. 2, 7, 1, etc. ; avec le gén. de la dette :</i> κ. τὸν δῆμον τῶν εἰσφορῶν, DS. <i>13, 64,</i> alléger le peuple du poids des impôts ; τόκων τοὺς χρεωφειλέτας, PLUT. <i>Cæs. 37,</i> alléger le chiffre des intérêts à la charge des débiteurs ; <i>avec un seul acc</i>. κ. τὰ ὀφλήματα, PLUT. <i>M. 807</i> d, diminuer les dettes ;<br><b>      2</b> <i>en parl. de maladies :</i> κ. τοὺς νοσοῦντας, PLUT. <i>M. 1106</i> b, soulager les malades ; κ. τὸ πάθος, PLUT. <i>Alex. 52,</i> alléger le mal ; <i>au pass. avec le gén. de la maladie :</i> κουφίζεσθαι νόσου, EUR. <i>Or. 43 ;</i> τοῦ πάθους, ARSTT. <i>Probl. 11, 10,</i> être soulagé d’une maladie, d’un mal ; <i>abs</i>. procurer du soulagement, HPC. <i>Epid. 1, 945 ;</i> ARSTT. <i>G.A. 1, 18, 52 ;</i><br><b>      3</b> <i>en parl. de chagrins,</i> soulager, consoler, <i>avec l’acc. de la chose :</i> κ. ἀλγηδόνας, EUR. <i>fr. 577,</i> soulager des souffrances ; <i>cf</i>. DÉM. <i>1400, 7 ;</i> THCR. <i>Idyl. 23, 9 ; au pass</i>. EUR. <i>Med. 473 ;</i> ARSTT. <i>Nic. 9, 1, 2 ;</i><br><b>   II</b> soulever : τινά, SOPH. <i>Tr. 1024,</i> qqn ; ἀσπίδ' ἀμφὶ βραχίονα, EUR. <i>Ph. 120,</i> soulever un bouclier et le tenir enlacé autour de son bras ; νεκρόν, SOPH. <i>Ant. 43,</i> enlever un mort, <i>pour lui donner la sépulture ; p. anal</i>. ἅλμα κ. SOPH. <i>Aj. 1287 ; ou</i> πήδημα κ. EUR. <i>El. 861,</i> sauter légèrement <i>ou</i> vivement ; <i>au pass</i>. ᾧ (πτερῷ) ἡ ψυχὴ κουφίζεται, PLAT. <i>Phædr. 248</i> c (l’aile) au moyen de laquelle l’âme s’élève légère ; <i>fig. au pass</i>. se laisser exalter (par l’espérance, <i>etc</i>.) POL. <i>14, 1, 11 ;</i><br><b>   III</b> <i>t. de gr</i>. élider, EUST. <i>p. 62, 45</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy. au sens pass</i>. κουφιοῦμαι, ARSTD. <i>46, 145</i>.<br><span><b>Étym</b>. κοῦφος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κουφιζω - κουφίζω</font>\n<br><br>vient de 'kouphos' (léger en poids)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G2894":"<h1>kophinos</h1>\n<p>Strong n° 2894 <i>Prononciation [kof'-ee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un panier, un panier d'osier, une corbeille. Mot français : un couffin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κόφινος, ου (ὁ)</b> <span>[ῐ]</span><br><b>      1</b> corbeille, AR. <i>Av. 1310 ;</i> XÉN. <i>Mem. 3, 8, 6, etc. ;</i><br><b>      2</b> mesure béotienne de 3 χόες pour les liquides et les matières sèches, ARSTT. <i>H.A. 9, 42, 4</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῑ]</span> NONN. <i>Jo. c. 6, v. 13, 52</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κοφινος - κόφινος</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2895":"<h1>krabbatos</h1>\n<p>Strong n° 2895 <i>Prononciation [krab'-bat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une paillasse, un grabat, un lit de camp, un lit plutôt simple ne pouvant contenir qu'une personne, une civière</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>κράϐϐατος, ου (ὁ)</b> lit de repos, <i>d’où</i> mauvais lit, grabat, RHINTHON <i>et</i> CRITON (POLL. <i>10, 35</i>) ; NT. <i>Marc. 2, 4, 9, etc. ; Joh. 5, 8 ; Ap. 5, 15, etc</i>.<br><span><b>Étym</b>. <i>mot macéd. selon Poll</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραβατος - κράβαττος</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (5)</li>\n<li>Jean (5)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G2896":"<h1>krazo</h1>\n<p>Strong n° 2896 <i>Prononciation [krad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>coasser, croasser\n<ol type=\"a\">\n<li>le cri du corbeau</li>\n<li>de là : crier, crier à haute voix, vociférer</li>\n<li>crier ou prier pour une vengeance</li>\n</ol>\n</li>\n<li>crier\n<ol type=\"a\">\n<li>s'écrier, parler d'une voix forte</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κράζω</b> <span>[ᾱ]</span> <span>(<i>f</i>. κεκράξομαι, <i>ao.2</i> ἔκραγον <span>[ᾰ]</span> <i>rar. ao.1</i> ἔκραξα, <i>pf. au sens du prés</i>. κέκραγα <span>[ᾱγ]</span>)</span><br><b>      1</b> pousser un cri rauque <i>ou</i> guttural, <i>en parl. du corbeau,</i> TH. <i>Sign. 4, 3, ou de la grenouille,</i> AR. <i>Ran. 258 ;</i><br><b>      2</b> <i>en parl. de l’homme,</i> crier fortement, vociférer, ESCHL. <i>Pr. 765 ; en parl. de Bacchus,</i> AR. <i>Ran. 265, etc. ; rar. en prose,</i> XÉN. <i>Cyr. 1, 3, 10 ;</i> LUC. <i>Tim. 7, etc. ; joint à</i> βοᾶν, DÉM. <i>271, 11 ;</i> κ. πρός τινα, AR. <i>Ran. 982,</i> appeler qqn à grands cris ; <i>avec un acc</i>. κρ. ὑπέρφρονα, SOPH. <i>Aj. 1236,</i> lancer avec force des paroles hautaines ; <i>avec une conj</i>. κεκραγὼς ὡς, DÉM. <i>271, 11,</i> ayant jeté les hauts cris, disant que, <i>etc. ;</i><br><b>      3</b> demander à grands cris, <i>acc</i>. AR. <i>Vesp. 103</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 avec redoubl</i>. ἐκέκραγον <span>[ᾰ]</span> SPT. <i>Esaï. 6, 4. Pf. impér</i>. κέκραχθι, AR. <i>Vesp. 198. Pl.q.pf. 2 pl</i>. ἐκεκράγετε, XÉN. <i>Cyr. 1, 2, 10</i>.<br><span><b>Étym</b>. <i>onomatopée</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραζω - κράζω</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – crier, comme manifestation de sentiment, de détresse\n<br><br> – crier, appeler pour un motif, dans un but\n<br><br> – crier avec rudesse, souvent avec un son inarticulé et brutal\n<br><br> – intensif de , crier grossièrement, avec mépris, etc.\n<br><br> suggère l'intelligence ;  la sensibilité ;  les instincts</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n57 fois dans 56 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (11)</li>\n<li>Luc (4)</li>\n<li>Jean (6)</li>\n<li>Actes (10)</li>\n<li>Romains (2)</li>\n<li>Galates (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G2897":"<h1>kraipale</h1>\n<p>Strong n° 2897 <i>Prononciation [krahee-pal'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>le vertige et mal de tête causés en buvant du vin à l'excès, débauche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κραιπάλη, ης (ἡ)</b> <span>[ᾰ]</span> lourdeur de tête produite par l’ivresse, <i>d’où</i> ivresse, ivrognerie, AR. <i>Ach. 277 ;</i> HPC. <i>Aër. 281 ;</i> PLUT. <i>M. 127</i> f.<br><span><b>Étym</b>. <i>cf</i>. κραιπνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κραιπαλη - κραιπάλη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G2898":"<h1>kranion</h1>\n<p>Strong n° 2898 <i>Prononciation [kran-ee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un crâne</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κρανίον, ου (τὸ)</b> <span>[ᾱ]</span><br><b>      1</b> crâne, IL. <i>8, 84 ;</i> PD. <i>I. 4, 92 ;</i> EUR. <i>Rhes. 679 ;</i> PLAT. <i>Euthyd. 299</i> e, <i>etc. ;</i><br><b>      2</b> tête, AMPHIS (ATH. <i>295</i> f).<br><span><b>Étym</b>. <i>cf</i>. κάρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρανιον - κρανίον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G2899":"<h1>kraspedon</h1>\n<p>Strong n° 2899 <i>Prononciation [kras'-ped-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'extrémité ou la partie proéminente d'une chose, bord, marge, la frange d'un vêtement\n<ol type=\"a\">\n<li>dans le N.T., un petit accessoire fait de laine tissée, qui pendait au bord du manteau ou du vêtement</li>\n<li>un gland, un pompon : les Juifs avaient de tels accessoires fixés à leur manteau pour leur rappeler la loi</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>κράσ·πεδον, ου (τὸ)</b> extrémité d’une chose, <i>d’où :</i><br><b>      1</b> bordure, frange d’un vêtement, <i>particul</i>. frange inférieure, THCR. <i>Idyl. 2, 53 ;</i> CHAMÆL. (ATH. <i>374</i> a) ; ATH. <i>159</i> d ; <i>au pl</i>. EUR. <i>Med. 524 ;</i> AR. <i>Vesp. 475 ;</i><br><b>      2</b> bord extrême, lisière, frontière d’un pays, d’un rivage, SOPH. <i>fr. 536 ;</i> EUR. <i>Thes. fr. 8 ;</i> ANTH. <i>7, 78 ;</i><br><b>      3</b> crête d’une montagne, XÉN. <i>Hell. 4, 6, 8 ;</i><br><b>      4</b> lisière d’un camp, EUR. <i>Suppl. 661 ;</i><br><b>      5</b> aile d’une armée, XÉN. <i>Hell. 3, 2, 16 ;</i><br><b>      6</b> maladie de la luette, ARÉT. <i>Cur. m. acut. 1</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">κρασπεδον - κράσπεδον</font>\n<br><br>dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>"};
